  'Not checked' => '未チェック',
  'We received your receipt, thank you 🌱 We\'ll get back to you about your payment as soon as possible.' => '領収書を受け取りました、ありがとうございます 🌱 お支払いについてはできるだけ早くご連絡いたします。',
  'We received your receipt, thank you 🌱 Your donation is confirmed.' => '領収書を受け取りました、ありがとうございます 🌱 寄付が確認されました。',
  'We had already received this receipt, thank you 🌱 We\'ll get back to you about your payment as soon as possible.' => 'この領収書はすでに受領しております。ありがとうございます 🌱 お支払いについてはできるだけ早くご連絡いたします。',
  'This receipt seems to have been uploaded to our system before. The same receipt cannot be used for a second donation. If you made a different payment, please send that receipt; our team will also check.' => 'この領収書は以前に当社のシステムにアップロードされたものと思われます。同じ領収書を二度目の寄付に使用することはできません。別の支払いをした場合は、その領収書をお送りください。私たちのチームもチェックします。',
  'We received your receipt. The amount on it (%1$s) does not seem to match your donation amount (%2$s). Could you check it? If you made a different payment, you can write here; our team will also take a look.' => '領収書を受け取りました。記載されている金額 (%1$s) が寄付金額 (%2$s) と一致していないようです。確認してもらえますか?別の支払いをした場合は、ここに記入できます。私たちのチームも検討します。',
  'We received your receipt, but the recipient on it does not seem to be our association. Donations are only made to our account in the name of "%s". Could you check? Our team will also take a look.' => '領収書を受け取りましたが、その受取人は当協会ではないようです。寄付は「%s」という名前のアカウントにのみ行われます。確認してもらえますか?私たちのチームも検討します。',
  'We received your receipt, but the recipient on it does not seem to match our account. Could you check? Our team will also take a look.' => '領収書を受け取りましたが、領収書に記載されている受取人が私たちのアカウントと一致していないようです。確認してもらえますか?私たちのチームも検討します。',
  'The file you sent does not look like a payment receipt. If you have paid, you can send the receipt or a screenshot of the payment screen here.' => '送信されたファイルは支払い領収書のようには見えません。支払いを行った場合は、領収書または支払い画面のスクリーンショットをここに送信できます。',
