  'Staff' => 'スタッフ',
  'No donations linked to you in this period.' => 'この期間中、あなたにリンクされた寄付はありません。',
  '📅 This month: %1$d donations · %2$s' => '📅 今月:%1$d寄付 ·%2$s',
  'WhatsApp reports' => 'WhatsApp レポート',
