  'Your profile has no WhatsApp number (Users › Profile).' => 'あなたのプロフィールには WhatsApp 番号がありません (ユーザー › プロフィール)。',
  'Scheduled donation reports for staff and managers; a short motivational line can be added at the end.' => 'スタッフとマネージャー向けの定期的な寄付レポート。最後に短い動機付けの行を追加できます。',
  'Saved.' => '保存されました。',
  '%d messages sent.' => '%dメッセージが送信されました。',
  'Reports need Flux Roles 1.1.0 and Flux Donations.' => 'レポートには Flux ロール 1.1.0 と Flux Donations が必要です。',
  'Report name' => 'レポート名',
  'To' => 'に',
  'Everyone who can receive reports' => 'レポートを受け取れる方全員',
  'Those who can see the overall report (managers)' => '全体レポートをご覧いただける方(管理者)',
  'Selected people' => '選ばれた人々',
  'Content' => '内容',
  'The person\'s own donations' => '本人の寄付',
  'Overall totals + per staff' => '全体の合計 + スタッフごと',
  'Period' => '期間',
  'Frequency' => '周波数',
  'Day of week' => '曜日',
  'Day of month' => '月の日',
  'Time' => '時間',
  'no number' => '番号なし',
  'Motivational lines (one per line; one is added at random to each report)' => '動機付けの行 (1 行に 1 つ、各レポートにランダムに 1 つ追加されます)',
  '%d recipients (with a registered number and permission).' => '%d受信者 (登録番号と許可あり)。',
  'Last sent: %s.' => '最終送信日:%s。',
  'Preview (for you)' => 'プレビュー (あなた向け)',
  'Send me a test' => 'テストを送ってください',
  'Send the report to all recipients now?' => '今すぐすべての受信者にレポートを送信しますか?',
  'Send to everyone now' => '今すぐ全員に送信',
  'Delete this report?' => 'このレポートを削除しますか?',
  '+ New report' => '+ 新しいレポート',
  'The recipient\'s number comes from Users › Profile › WhatsApp number; permissions from Users › Roles and access (receive reports, view overall report, manage reports). Reports go out at the chosen time; without a server scheduler they are sent on the next site visit or chat panel use.' => '受信者の番号は、ユーザー › プロフィール › WhatsApp 番号から取得されます。ユーザーからの権限 › 役割とアクセス (レポートの受信、レポート全体の表示、レポートの管理)。レポートは選択した時間に送信されます。サーバー スケジューラを使用しないと、次回のサイト訪問時またはチャット パネルの使用時に送信されます。',
  'Invalid phone number.' => '電話番号が無効です。',
  'First add a WhatsApp connection under Settings › Connections.' => 'まず、[設定] › [接続] で WhatsApp 接続を追加します。',
  '%1$s assigned the chat to %2$s' => '%1$sがチャットを%2$sに割り当てました',
  '%s removed the chat assignment' => '%sがチャット割り当てを削除しました',
  '%s closed the chat' => '%sがチャットを閉じました',
  '%s reopened the chat' => '%sがチャットを再開しました',
  'File is too large (max %s).' => 'ファイルが大きすぎます (最大%s)。',
  'This file type cannot be sent.' => 'この種類のファイルは送信できません。',
  'File could not be uploaded.' => 'ファイルをアップロードできませんでした。',
  'This message cannot be resent.' => 'このメッセージは再送信できません。',
  'Can\'t react to this message.' => 'このメッセージには反応できません。',
  'You can only delete your own notes.' => '削除できるのは自分のメモのみです。',
  'Reply text cannot be empty.' => '返信テキストを空にすることはできません。',
  'Connection not found. Save the settings first.' => '接続が見つかりません。まず設定を保存します。',
  'The message was only image code; it was not sent.' => 'メッセージは画像コードのみでした。送信されませんでした。',
  'This contact is blocklisted; no messages are sent. Remove them from the blocklist to write again.' => 'この連絡先はブロックリストに登録されています。メッセージは送信されません。再度書き込むには、ブロックリストから削除してください。',
  'Message could not be saved.' => 'メッセージを保存できませんでした。',
  'This contact writes from a hidden WhatsApp number (@lid) and Evolution API (version %s) could not send to this address. Update the Evolution API server to 2.3 or later; if the contact\'s real number arrives, the plugin sends there.' => 'この連絡先は非表示の WhatsApp 番号 (@lid) から書き込みを行っており、Evolution API (バージョン%s) はこのアドレスに送信できませんでした。 Evolution API サーバーを 2.3 以降に更新します。連絡先の実番号が到着すると、プラグインはそこに送信します。',
  'This contact writes from a hidden WhatsApp number (@lid) and Evolution API could not send to this address. Update the Evolution API server to 2.3 or later; if the contact\'s real number arrives, the plugin sends there.' => 'この連絡先は非表示の WhatsApp 番号 (@lid) から書き込んでいるため、Evolution API はこのアドレスに送信できませんでした。 Evolution API サーバーを 2.3 以降に更新します。連絡先の実番号が到着すると、プラグインはそこに送信します。',
  'No WhatsApp connection.' => 'WhatsApp 接続がありません。',
  'Connected ✓' => '接続済み ✓',
  'Not connected (state: %s). Connect with QR.' => '接続されていません (状態:%s)。 QRで接続します。',
  'Webhook points to this site ✓' => 'Webhook はこのサイトを指します ✓',
  'Evolution API version: %s' => 'Evolution API バージョン:%s',
  '(old: replies to hidden-number (@lid) contacts may fail, update to 2.3 or later)' => '(旧: 非表示の番号 (@lid) 連絡先への返信が失敗する場合がある。2.3 以降に更新してください)',
  'The webhook is not pointed at this site. Press "Set up webhook".' => 'Webhook はこのサイトを指していません。 「Webhookを設定する」を押します。',
  'Webhook set up ✓ Incoming messages will now arrive here.' => 'Webhook の設定 ✓ 受信メッセージがここに到着します。',
  'Importing recent chats, this may take a while…' => '最近のチャットをインポートしています。これにはしばらく時間がかかる場合があります...',
  'Messages stored in Evolution: %s' => 'Evolution に保存されたメッセージ:%s',
  'Evolution does not store messages, so older messages cannot be loaded. On the Evolution server set DATABASE_SAVE_DATA_NEW_MESSAGE and DATABASE_SAVE_DATA_HISTORIC to true; for older conversations, keep "Sync full history" on in the instance settings when you reconnect the line with QR.' => 'Evolution はメッセージを保存しないため、古いメッセージをロードすることはできません。 Evolution サーバーで、DATABASE_SAVE_DATA_NEW_MESSAGE と DATABASE_SAVE_DATA_HISTORIC を true に設定します。古い会話の場合は、QR で回線を再接続するときにインスタンス設定で [全履歴を同期] をオンのままにします。',
  '%1$s chats, %2$s messages imported ✓' => '%1$sチャット、%2$sメッセージのインポート ✓',
  'Scan this code via WhatsApp › Linked devices › Link a device.' => 'WhatsApp › リンクされたデバイス › デバイスをリンクしてこのコードをスキャンします。',
  'Pairing code:' => 'ペアリングコード:',
  'This line is already connected ✓' => 'この回線はすでに接続されています ✓',
  'Save the settings first.' => 'まず設定を保存します。',
  'Error:' => 'エラー:',
  'Delete this connection? Chat history is kept.' => 'この接続を削除しますか?チャット履歴は保存されます。',
  'Asking the AI…' => 'AIに聞いてみると...',
  'Working ✓ (%2$s ms): %1$s' => '動作中 ✓ (%2$sミリ秒):%1$s',
  'Save the key and model first.' => 'まずキーとモデルを保存します。',
  'Connections' => '接続',
  'Auto replies' => '自動返信',
  'AI and assistant' => 'AIとアシスタント',
  'System check' => 'システムチェック',
  'Connect your WhatsApp line, manage auto replies and labels.' => 'WhatsApp 回線に接続し、自動返信とラベルを管理します。',
  'Open chats' => 'オープンチャット',
  'Settings saved.' => '設定が保存されました。',
  'Connections and settings the call center needs. Saved status is shown; use the "test" buttons on each tab for a live check. The same checks also appear with the other plugins on the theme\'s system-check screen.' => 'コールセンターに必要な接続と設定。保存されたステータスが表示されます。ライブチェックには各タブの「テスト」ボタンを使用してください。テーマのシステムチェック画面では、他のプラグインにも同じチェックが表示されます。',
  'WhatsApp lines' => 'WhatsApp ライン',
  'Messages are sent and received through Evolution API. WhatsApp connections are managed in Flux Mail; choose which one to use here. The URL and API key stay there, so you do not need to update them here when they change.' => 'メッセージはEvolution APIを通じて送受信されます。 WhatsApp 接続は Flux Mail で管理されます。ここでどれを使用するかを選択します。 URL と API キーはそこに残るため、変更されたときにここで更新する必要はありません。',
  'Communication › Connections' => 'コミュニケーション › 接続',
  'Messages are sent and received via Evolution API. If an Evolution provider is set up in Flux Certificates, you can pick the same connection; the URL and API key stay there.' => 'メッセージはEvolution APIを介して送受信されます。 Evolution プロバイダーが Flux 証明書で設定されている場合は、同じ接続を選択できます。 URL と API キーはそこに残ります。',
  'Add line' => '行を追加',
  'Setup steps' => 'セットアップ手順',
  'Add the line and save.' => '行を追加して保存します。',
  'Use "Test connection" to see that Evolution is reachable. If the line is not linked, choose "Connect with QR" and scan it from the phone.' => '「テスト接続」を使用して、Evolution に到達できることを確認します。回線がリンクされていない場合は、「QRで接続」を選択し、携帯電話からスキャンしてください。',
  'Press "Set up webhook". Incoming messages, and messages sent from the phone and from Flux Certificates, then appear here live.' => '「Webhookを設定する」を押します。受信メッセージ、電話や Flux 証明書から送信されたメッセージは、ここにライブで表示されます。',
  'Optionally bring in past messages with "Import recent chats".' => '必要に応じて、「最近のチャットをインポート」を使用して過去のメッセージを取り込みます。',
  'connected' => '接続されています',
  'connecting' => '接続する',
  'not connected' => '接続されていません',
  'not on server' => 'サーバー上にない',
  'unreachable' => '到達不可能な',
  'Flux Mail connection: %s' => 'Flux メール接続:%s',
  'Flux Mail connection #%d (not found or disabled)' => 'Flux Mail 接続 #%d(見つからないか無効になっています)',
  'Use Flux Certificates provider: %s' => 'Flux 証明書プロバイダーを使用:%s',
  'Enter separate Evolution API details' => 'Evolution API の詳細を個別に入力します',
  'Line name (e.g. Main line)' => '路線名(例:幹線)',
  'Connection details' => '接続の詳細',
