  'Webhook URL' => 'Webhook URL',
  'Regenerate secret key' => '秘密鍵を再生成する',
  'Last webhook: %s' => '最後の Webhook:%s',
  'No webhook received yet.' => 'Webhook はまだ受信されていません。',
  'Test connection' => 'テスト接続',
  'Connect with QR' => 'QRでつながる',
  'QR, status and accounts: Communication › Connections' => 'QR、ステータス、アカウント: コミュニケーション › 接続',
  'Set up webhook' => 'Webhook を設定する',
  'Import recent chats' => '最近のチャットをインポートする',
  'The webhook URL and test buttons appear after saving.' => '保存すると、Webhook URL とテスト ボタンが表示されます。',
  'Appearance' => '外観',
  'Panel title' => 'パネルタイトル',
  'Site name if empty. The {brand} variable uses this too.' => '空の場合はサイト名。{brand}変数もこれを使用します。',
  'Accent color' => 'アクセントカラー',
  'Behavior' => '行動',
  'Send read receipts (blue ticks) when a chat is opened' => 'チャットを開いたときに開封確認 (青いチェックマーク) を送信します',
  'Prefix messages with the agent\'s name (*Name:*)' => 'メッセージの前にエージェント名を付けます (*Name:*)',
  'Agents see only chats assigned to them and unassigned chats (admins see all)' => 'エージェントには、自分に割り当てられたチャットと割り当てられていないチャットのみが表示されます (管理者にはすべてが表示されます)',
  'Also show WhatsApp group messages' => 'WhatsApp グループメッセージも表示します',
  'New interface (experimental): the Chats page opens with the same screen as the desktop and mobile app' => '新しいインターフェイス (実験的): デスクトップおよびモバイル アプリと同じ画面でチャット ページが開きます。',
  'Live update interval (sec)' => 'ライブアップデート間隔(秒)',
  'Agents' => 'エージェント',
  'Give a user the %s role; they see only the chat screen and cannot open settings. Administrators always have access.' => 'ユーザーに%sロールを与えます。チャット画面のみが表示され、設定を開くことはできません。管理者は常にアクセスできます。',
  'Add new user' => '新しいユーザーを追加',
  'Data' => 'データ',
  'Also delete all chats, messages and media files when the plugin is deleted' => 'プラグインを削除すると、すべてのチャット、メッセージ、メディア ファイルも削除されます。',
  'Media files are kept in wp-content/uploads/flx-chat, closed to outside access. They move with uploads when the site is migrated.' => 'メディア ファイルは wp-content/uploads/flx-chat に保管され、外部からのアクセスは禁止されています。サイトが移行されると、アップロードとともに移動します。',
  'Mon' => '月',
  'Tue' => '火',
  'Wed' => '水',
  'Thu' => '木',
  'Fri' => '金',
  'Sat' => '土',
  'Sun' => '太陽',
  'Welcome message' => 'ウェルカムメッセージ',
  'Send automatically to people who write to us for the first time' => '初めてメールを送信する人に自動的に送信します',
  'Away message' => 'アウェイメッセージ',
  'Auto reply to messages received outside business hours' => '営業時間外に受信したメッセージには自動返信します',
  'Business days' => '営業日',
  'Start' => 'スタート',
  'End' => '終了',
  'At most once per contact every (hours)' => '連絡先ごとに最大 1 回(時間ごと)',
  'Timezone: %1$s. Now: %2$s.' => 'タイムゾーン:%1$s。現在:%2$s。',
  'within business hours' => '営業時間内',
  'outside business hours' => '営業時間外',
  'The {first_name}, {name}, {brand}, {site}, {date} variables can be used in the texts.' => '{first_name}、{name}、{brand}、{site}、{date}変数はテキスト内で使用できます。',
  'Chat labels' => 'チャットラベル',
  'Label chats and filter the list (e.g. Donation, Complaint, Follow-up).' => 'チャットにラベルを付けてリストをフィルタリングします (寄付、苦情、フォローアップなど)。',
  'Add label' => 'ラベルを追加する',
  'Label name' => 'レーベル名',
  'Creating records from chats' => 'チャットからレコードを作成する',
  'Buttons in the chat header create a donation record (Flux Donate) and a certificate (Flux Certificates), and an incoming receipt is matched with a record. If a plugin is not installed, its button is hidden.' => 'チャット ヘッダーのボタンにより寄付レコード (Flux Donate) と証明書 (Flux Certificates) が作成され、受信した領収書がレコードと照合されます。プラグインがインストールされていない場合、そのボタンは非表示になります。',
  'Agents can create donation records and match receipts' => 'エージェントは寄付記録を作成し、領収書を照合できます',
  'Agents can create and send certificates' => 'エージェントは証明書を作成して送信できます',
  'Show quick reply bubbles above the message box' => 'メッセージ ボックスの上にクイック返信バブルを表示する',
  'Donation messages' => '寄付メッセージ',
  'Ready texts sent to the person when a record is created (editable before sending). If left empty, the default text is used.' => 'レコードの作成時にその人に送信される準備完了のテキスト (送信前に編集可能)。空のままにすると、デフォルトのテキストが使用されます。',
  'Awaiting payment (promised transfer)' => '支払い待ち(約束された送金)',
  'Donation received' => '寄付金を受け取りました',
  'Receipt confirmed' => '受領確認済み',
  'Bank details ({bank})' => '銀行詳細 ({bank})',
  'Recipient name, bank, IBAN' => '受取人の名前、銀行、IBAN',
  'If empty, the account in WooCommerce › Payments › Bank transfer is used.' => '空の場合、WooCommerce › 支払い › 銀行振込のアカウントが使用されます。',
  'Variables: {first_name}, {name}, {donation}, {amount}, {quantity}, {bank}, {certificate_link}, {agent}, {brand}, {date}.' => '変数:{first_name}、{name}、{donation}、{amount}、{quantity}、{bank}、{certificate_link}、{agent}、{brand}、{date}。',
  'AI connection' => 'AI接続',
  'Keys, prompt caching, spending limits and usage logs come from the Flux AI & MCP plugin; all of the Call Center\'s AI requests go through it. Model choices stay here; if a field is empty, the model chosen for this plugin in Flux AI (or the default) is used.' => 'キー、プロンプト キャッシュ、支出制限、使用ログは Flux AI および MCP プラグインから取得されます。コールセンターの AI リクエストはすべてそれを通過します。モデルの選択はここに留まります。フィールドが空の場合、Flux AI でこのプラグイン用に選択されたモデル (またはデフォルト) が使用されます。',
  'Open Flux AI settings' => 'Flux AI 設定を開く',
  'AI needs the Flux AI & MCP plugin. Install and activate it, then enter the OpenRouter and/or Anthropic key in Flux AI & MCP › Settings. Until then suggestions, the assistant, receipt reading, voice messages and summaries are off.' => 'AI には Flux AI および MCP プラグインが必要です。インストールしてアクティベートし、Flux AI と MCP › 設定に OpenRouter キーや Anthropic キーを入力します。それまでは、提案、アシスタント、レシートの読み上げ、音声メッセージ、概要はオフになります。',
  'Creativity (0–1)' => '創造性 (0–1)',
  'Lower values give more consistent replies, higher values freer ones. 0.4 recommended.' => '値が低いほど一貫性のある応答が得られ、値が高いほど自由な応答が得られます。 0.4をお勧めします。',
  'Model (for suggestions)' => 'モデル(提案用)',
  'Assistant model (optional)' => 'アシスタントモデル(オプション)',
  'Model above' => '上記のモデル',
  'Only models that support tools are listed.' => 'ツールをサポートするモデルのみがリストされています。',
  'Receipt reading model (optional)' => 'レシート読み取りモデル(オプション)',
  'If the selected model cannot read images, a cheap vision model is used automatically.' => '選択したモデルが画像を読み取れない場合は、安価なビジョンモデルが自動的に使用されます。',
  'This month (%1$s): %2$s requests, %3$s tokens, about $%4$s.' => '今月 (%1$s):%2$sリクエスト、%3$sトークン、約 $%4$s。',
  'Reply suggestions' => '返信の提案',
  'Above the message box, the next message is suggested from the conversation. The agent clicks "Send" or takes it into the box with "Edit". A suggestion is never sent on its own.' => 'メッセージ ボックスの上に、会話から次のメッセージが提案されます。エージェントは「送信」をクリックするか、「編集」でボックスにそれを取り込みます。提案が単独で送信されることはありません。',
  'Prepare a suggestion automatically when the last message came from the person (if off, ask with the ✨ button)' => '相手から最後のメッセージが届いたときに自動的に提案を準備します (オフの場合は、✨ ボタンで質問します)',
  'Organization info and tone' => '組織の情報とトーン',
  'E.g. Our association plants saplings in Istanbul. Planting is done every year between November and March. The certificate is sent on WhatsApp after the donation. Use a warm but formal tone.' => '例:私たちの協会はイスタンブールで苗木を植えています。植え付けは毎年11月から3月の間に行われます。証明書は寄付後にWhatsAppで送信されます。温かみのある、しかしフォーマルな口調を使用します。',
  'Suggestions and the assistant use this. Donation types, prices, bank details and quick replies are added automatically.' => '提案とアシスタントはこれを使用します。寄付の種類、価格、銀行詳細、クイック返信が自動的に追加されます。',
  'Suggestion provider' => '提案プロバイダー',
  'Donation assistant (automatic replies)' => '寄付アシスタント(自動返信)',
  'When on, the assistant replies itself: it greets, asks the name to address them, sends donation options and prices, optionally collects email and "in whose name", and asks for confirmation after each change. After confirmation it opens an "awaiting payment" record in Flux Donate and sends the donation link, recipient, IBAN and reference as separate messages. If the topic leaves donations, it hands the chat to the team.' => 'オンの場合、アシスタントは自ら応答します。挨拶し、宛先を尋ねる名前を尋ね、寄付のオプションと価格を送信し、オプションで電子メールと「誰の名前で」を収集し、変更のたびに確認を求めます。確認後、Flux Donate で「支払い待ち」レコードが開き、寄付リンク、受取人、IBAN、参照先が別のメッセージとして送信されます。トピックが寄付を残すと、チャットがチームに渡されます。',
  'The Flux Donate plugin is not active; the assistant cannot create donation records.' => 'Flux Donate プラグインはアクティブではありません。アシスタントは寄付記録を作成できません。',
  'Instructions, documents, AI chats and test chat' => '説明書、ドキュメント、AI チャット、テスト チャット',
  'Turn on the donation assistant (untick to turn it off everywhere)' => '寄付アシスタントをオンにします (どこでもオフにするにはチェックを外します)',
  'Which chats should it reply to' => 'どのチャットに返信すべきか',
  'In all chats (recommended)' => 'すべてのチャットで (推奨)',
  'In chats not assigned to an agent' => 'エージェントに割り当てられていないチャット内',
  'Only outside working hours' => '勤務時間外のみ',
  'When an agent writes in a chat (from the panel or the phone), the assistant stays quiet there for the time below. Use the assistant button in the chat header to turn it on or off per chat.' => 'エージェントが (パネルまたは電話から) チャットに書き込みを行うと、アシスタントは以下の時間の間、そこで沈黙を保ちます。チャット ヘッダーのアシスタント ボタンを使用して、チャットごとにオンまたはオフにします。',
  'Test mode: reply only to the numbers below' => 'テストモード: 以下の番号にのみ返信してください',
  'Test numbers' => '検査番号',
  'Separate with commas or new lines. Not used when test mode is off.' => 'カンマまたは改行で区切ります。テストモードがオフの場合は使用されません。',
  'Quiet after an agent writes (hours)' => 'エージェントが書き込みを行った後は静かになります (時間)',
  'Quantities in the price list' => '価格表の数量',
  'Conversation history (hours)' => '会話履歴(時間)',
  'Before replying, the assistant reads all messages from this period.' => '応答する前に、アシスタントはこの期間のすべてのメッセージを読みます。',
  'Donation types the assistant offers' => 'アシスタントが提供する寄付の種類',
  'If none is selected, all open types are offered. When a new type is opened in Flux Donate, the assistant knows it too.' => '何も選択されていない場合は、すべてのオープン タイプが提供されます。新しいタイプが Flux Donate で開かれると、アシスタントもそれを認識します。',
  'Receipt pre-check: when the contact sends a receipt, AI compares the amount, recipient and IBAN with the donation, tells the contact the result, attaches the file to the donation record and hands the chat to the team for final approval (does not mark it paid)' => '領収書の事前チェック: 連絡先が領収書を送信すると、AI が金額、受取人、および IBAN を寄付と比較し、結果を連絡先に伝え、ファイルを寄付記録に添付して、最終承認のためにチャットをチームに渡します (支払い済みとはマークされません)。',
  'Last line of the price list' => '価格表の最後の行',
  'Payment details' => 'お支払い詳細',
  'If the recipient and IBAN are empty, those in WooCommerce › Payments › Bank transfer are used (the account shown on orders). Fill them in only if the assistant should use a different account.' => '受信者と IBAN が空の場合、WooCommerce › 支払い › 銀行振込のものが使用されます (注文に表示されているアカウント)。アシスタントが別のアカウントを使用する必要がある場合にのみ入力してください。',
  'Recipient name' => '受信者名',
  'Transfer description' => '転送の説明',
  'Variables: {type}, {name}, {amount}, {quantity}' => '変数:{type}、{name}、{amount}、{quantity}',
  'Donation page URL' => '寄付ページURL',
  'The selected type and quantity are added to the link (?flxb_opt=…&flxb_qty=…).' => '選択したタイプと数量がリンクに追加されます (?flxb_opt=...&flxb_qty=...)。',
  'Message after the payment details' => '支払い詳細後のメッセージ',
  'Donation cancellation question' => '寄付キャンセルに関する質問',
  'The assistant cancels only unpaid donations, with the person\'s confirmation. Empty = default text. Variables: {bagis}, {tutar}.' => 'アシスタントは、本人の確認を得て、未払いの寄付のみをキャンセルします。空 = デフォルトのテキスト。変数:{bagis}、{tutar}。',
  'Message sent when the daily limit is reached' => '1 日の制限に達したときに送信されるメッセージ',
  'Sent once when a chat reaches the day\'s reply limit; the chat is handed to the team. Reset it from the chat\'s ⋮ menu › Assistant usage.' => 'チャットがその日の返信制限に達したときに 1 回送信されます。チャットはチームに渡されます。チャットの ⋮ メニュー › アシスタントの使用状況からリセットします。',
  'Message sent when handing over to the team' => 'チームへの引き継ぎ時に送信されるメッセージ',
  'Message sent when the assistant cannot answer' => 'アシスタントが応答できないときに送信されるメッセージ',
  'If the AI fails, the time limit is hit or the queue gets too long, this message is sent and the chat is handed to the team; the person is never left without an answer.' => 'AI が失敗した場合、制限時間に達した場合、またはキューが長すぎる場合、このメッセージが送信され、チャットはチームに渡されます。その人が答えを持たずに放置されることは決してありません。',
  'Minimum wait before the holding message (s)' => 'メッセージを保持するまでの最小待機時間 (複数可)',
  'The holding message is not sent until this many seconds after the person\'s message; meanwhile the assistant retries.' => '保留中のメッセージは、その人のメッセージからこの秒数が経過するまで送信されません。その間、アシスタントは再試行します。',
  'Longest time for one answer (s)' => '1 つの回答にかかる最長時間 (秒)',
  'Hostinger can cut requests at ~60 s; 50 is recommended.' => 'Hostinger はリクエストを最大 60 秒でカットできます。 50が推奨されます。',
  'Numbers notified on handoff' => 'ハンドオフ時に通知される番号',
  'When the assistant hands a chat over to the team, a WhatsApp message is sent to these numbers from the same line: the contact\'s name, phone, reason, last messages and panel link. Separate with commas or new lines. The assistant does not talk to these numbers.' => 'アシスタントがチャットをチームに引き渡すと、連絡先の名前、電話番号、理由、最後のメッセージ、パネル リンクといった WhatsApp メッセージが同じ回線からこれらの番号に送信されます。カンマまたは改行で区切ります。アシスタントはこれらの番号とは会話しません。',
  'When the contact writes one of these, the assistant immediately sends the hand-off message above and turns off in that chat. If left empty, the example list is used.' => '連絡先がこれらのいずれかを書き込むと、アシスタントはすぐに上記のハンドオフ メッセージを送信し、そのチャットをオフにします。空のままにすると、サンプルのリストが使用されます。',
  'Extra instructions for the assistant' => 'アシスタントへの追加指示',
  'E.g. Saplings are planted in Kocaeli. Certificates are sent once the donation is confirmed.' => '例:コジャエリには苗木が植えられています。寄附確認後に証明書を発送いたします。',
  'Last message when a contact opts out' => '連絡先がオプトアウトしたときの最後のメッセージ',
  'If someone writes something like "don\'t message me", the assistant sends this message and blocklists them. A blocklisted person gets no WhatsApp, email or SMS; manage the list under Chats › ☰ › Blocklist.' => '誰かが「メッセージを送らないでください」のような内容を書き込んだ場合、アシスタントはこのメッセージを送信し、ブロックリストに登録します。ブロックリストに登録された人は、WhatsApp、電子メール、SMS を受け取りません。チャット › ☰ › ブロックリストでリストを管理します。',
  'Contact memory and background jobs' => 'コンタクトメモリとバックグラウンドジョブ',
  'Contact memory: the assistant remembers lasting details (form of address, relatives\' names, numbers, preferences); expired chats are summarized' => '連絡先の記憶: アシスタントは永続的な詳細 (住所の形式、親戚の名前、番号、好み) を記憶します。期限切れのチャットがまとめられています',
  'Summarize a chat after it has been quiet for (hours)' => '(時間) 沈黙が続いた後にチャットを要約する',
  'Maximum jobs at the same time' => '同時に最大ジョブ数',
  'How many people can be answered at the same time. Assistant replies always come first; summaries do not start while someone is being answered or waiting. Each job uses one PHP worker: on shared hosting, stay under half of the total worker limit of your sites (e.g. 20-30 of 60 workers).' => '同時に何人まで回答できるか。アシスタントの応答は常に最初に行われます。誰かが応答しているか待っている間は、要約は開始されません。各ジョブは 1 つの PHP ワーカーを使用します。共有ホスティングでは、サイトの総ワーカー制限の半分未満に抑えてください (例: 60 ワーカーのうち 20 ~ 30 人)。',
  'Workers reserved for replies' => '返信用に予約されたワーカー',
  'This many workers never take summaries or reminders.' => 'これほど多くの従業員は、概要やリマインダーをまったく受け取らないのです。',
  'Summary hours' => '概要時間',
  'Summaries run only between these hours (except a manual "Summarize now"). If both are the same, any time.' => '要約は、これらの時間の間にのみ実行されます (手動の「今すぐ要約」を除く)。両方が同じであればいつでも。',
  'When someone sends a voice message, the assistant turns it into text and replies (the text also appears in the panel as a system line)' => '誰かが音声メッセージを送信すると、アシスタントがそれをテキストに変換して返信します (テキストはシステム行としてもパネルに表示されます)。',
  'Longest voice message (sec)' => '最長の音声メッセージ (秒)',
  'For longer messages the assistant says "the voice message was too long for us to listen to".' => '長いメッセージの場合、アシスタントは「音声メッセージが長すぎて聞くことができませんでした」と言います。',
  'Voice message model (optional)' => '音声メッセージモデル(オプション)',
  'Cheap audio model (Gemini Flash Lite)' => '廉価オーディオモデル(Gemini Flash Lite)',
  'Must be an OpenRouter model that accepts audio (Claude does not). An OpenRouter key is required.' => 'オーディオを受け入れる OpenRouter モデルである必要があります (Claude は受け入れません)。 OpenRouter キーが必要です。',
  'Images' => '画像',
  'Let the assistant draw an image when useful (table, report, diagram); it goes to WhatsApp as a picture, the text is sent separately' => '必要に応じてアシスタントに画像 (表、レポート、図) を描画させます。 WhatsApp に画像として送信され、テキストは個別に送信されます',
  'The Flux AI image renderer is used (Flux AI & MCP › Settings › Images).' => 'Flux AI イメージ レンダラーが使用されます (Flux AI と MCP › 設定 › 画像)。',
  'No image renderer on the server: enter a Gotenberg address in Flux AI & MCP › Settings › Images or install Imagick (SVG). Until then the assistant does not draw images.' => 'サーバー上に画像レンダラーがありません: Flux AI & MCP › 設定 › 画像 に Gotenberg アドレスを入力するか、Imagick (SVG) をインストールします。それまでアシスタントは画像を描画しません。',
  'Works once Flux AI 0.2.0 or later is installed.' => 'Flux AI 0.2.0 以降がインストールされていると動作します。',
  'Donation on behalf of someone' => '誰かに代わって寄付する',
  'If the donation is in someone else\'s name and their number was given (contact card or typed number), also send the certificate to that number on WhatsApp once the payment is approved' => '寄付が他人の名前であり、その番号が指定されている場合(連絡先カードまたは入力された番号)、支払いが承認されたら、WhatsApp のその番号にも証明書を送信してください。',
  'Message sent before the certificate' => '証明書の前にメッセージが送信される',
  'Then the WhatsApp certificate message from Flux Certificates is sent. Variables: {ad}, {bagisci}, {bagis}, {brand}.' => '次に、Flux Certificates から WhatsApp 証明書メッセージが送信されます。変数:{ad}、{bagisci}、{bagis}、{brand}。',
  'If a person asks, the assistant sets up a reminder (e.g. "remind me of sapling planting every month", "send me your latest projects every month", "ask me for a sapling every month"); when it is due, the assistant writes and sends the message' => '誰かが尋ねると、アシスタントはリマインダーを設定します(例:「毎月苗木を植えることを思い出させて」、「毎月最新のプロジェクトを送って」、「毎月苗木をくれと頼んで」)。期限が来ると、アシスタントがメッセージを書いて送信します',
  'When no time is given' => '時間が与えられないとき',
  'At most per person' => '最大でもお一人様あたり',
  'Staff (Flux Roles)' => 'スタッフ (フラックスの役割)',
  'Works once Flux Roles 1.1.0 is installed: users whose number is set in Profile › WhatsApp number get extra assistant tools based on their permissions.' => 'Flux ロール 1.1.0 がインストールされると機能します。番号が [プロファイル] › WhatsApp 番号に設定されているユーザーは、権限に基づいて追加のアシスタント ツールを取得します。',
  'Give staff numbers extra assistant tools by permission (donation on behalf of someone with payment link, my donors, general report)' => '許可を得てスタッフ番号に追加のアシスタント ツールを提供します (支払いリンクを持つ誰かに代わって寄付、私の寄付者、一般的なレポート)',
  'Notify staff on WhatsApp when a donation they referred is paid or cancelled' => '紹介した寄付が支払われたとき、またはキャンセルされたときにスタッフに WhatsApp で通知する',
  'First message to the donor for a donation opened by staff' => 'スタッフが開く寄付者への最初のメッセージ',
  'Hello {ad} 🌱 Your {bagis} donation request via {personel} has been received. You can pay with the details below.' => 'こんにちは{ad}🌱{personel}経由で{bagis}の寄付リクエストを受け取りました。以下の詳細でお支払いいただけます。',
  'The payment link and bank details follow. Variables: {ad}, {adsoyad}, {personel}, {bagis}.' => '支払いリンクと銀行の詳細が続きます。変数:{ad}、{adsoyad}、{personel}、{bagis}。',
  'When a donation referred by a staff member is paid and its certificates are made, send them to the staff member on WhatsApp too (just like the donor)' => 'スタッフメンバーから紹介された寄付金が支払われ、証明書が作成されたら、それを WhatsApp でスタッフメンバーにも送信します (寄付者と同じように)',
  'Message sent to the staff member before the certificate' => '証明書を受け取る前にスタッフに送信されたメッセージ',
  'Variables: {ad}, {bagisci}, {bagis}, {no}, {brand}.' => '変数:{ad}、{bagisci}、{bagis}、{no}、{brand}。',
  'How many times staff can resend a donation\'s certificate' => 'スタッフが寄付証明書を何回再送できるか',
  'The assistant lists the recipients and asks for confirmation before sending. 0: off.' => 'アシスタントは受信者をリストし、送信する前に確認を求めます。 0: オフ。',
  'Code verification for record lookups' => 'レコード検索のコード検証',
  'When a person asks for their records and their number is hidden (or they donated with another number/e-mail), send a code to the number or e-mail they give; once verified, its records are shown too' => '誰かが自分の記録を要求し、その番号が隠されている場合(または別の番号/電子メールで寄付した場合)、その人が提供した番号または電子メールにコードを送信します。確認されると、その記録も表示されます',
  'Code validity (min)' => 'コードの有効性 (分)',
  'Maximum failed attempts' => '失敗した試行の最大数',
  'Codes that could not be sent, wrong codes and expired codes count. At the limit the person gets the message below and the team is notified; the assistant keeps answering other questions but shares no record details for 24 hours.' => '送信できなかったコード、間違ったコード、期限切れのコードもカウントされます。制限に達すると、その人は以下のメッセージを受け取り、チームに通知されます。アシスタントは他の質問に答え続けますが、記録の詳細は 24 時間共有されません。',
  'Code to phone' => '電話へのコード',
  'WhatsApp, SMS if it fails' => 'WhatsApp、失敗した場合はSMS',
  'WhatsApp only' => 'WhatsAppのみ',
  'SMS only' => 'SMSのみ',
  'SMS is used if Flux Mail has an SMS connection (e.g. Netgsm).' => 'Flux Mail に SMS 接続 (Netgsm など) がある場合、SMS が使用されます。',
  'Message when verification fails' => '検証失敗時のメッセージ',
  'WhatsApp/SMS code message' => 'WhatsApp/SMS コードメッセージ',
  'Default text if empty. Variables: {kod}, {dk}, {marka}. The e-mail text is edited in Flux Mail › E-mail templates.' => '空の場合のデフォルトのテキスト。変数:{kod}、{dk}、{marka}。電子メールのテキストは、Flux Mail › 電子メール テンプレートで編集します。',
  'Site content' => 'サイトのコンテンツ',
  'Let the assistant search published site content (e.g. "do you have a post about tree planting")' => 'アシスタントが公開されているサイトのコンテンツを検索できるようにします (例: 「植樹に関する投稿はありますか」)',
  'Content types to search' => '検索するコンテンツの種類',
  'Only published content without a password is returned. Drafts, private and password-protected content are never shown.' => 'パスワードなしで公開されたコンテンツのみが返されます。下書き、プライベート、パスワードで保護されたコンテンツは表示されません。',
  'Categories and tags never to share' => '決して共有しないカテゴリとタグ',
  'e.g. corporate-offers, internal-notice' => '例:企業オファー、社内通知',
  'Name or slug, comma separated. To hide a single item, tick "Do not let the assistant share this content" on its edit screen.' => '名前またはスラッグ、カンマ区切り。単一のアイテムを非表示にするには、その編集画面で「アシスタントにこのコンテンツを共有させない」にチェックを入れます。',
  'Team group' => 'チームグループ',
  'WhatsApp group' => 'WhatsAppグループ',
  '— Not selected —' => '— 未選択 —',
  'Groups the line is a member of. If a group you just created is missing,' => 'ラインがメンバーとなっているグループ。作成したばかりのグループが見つからない場合は、',
  'refresh the list' => 'リストを更新する',
  'Post incoming messages and replies (assistant, team, automatic) to this group' => '受信メッセージと返信 (アシスタント、チーム、自動) をこのグループに投稿します',
  'Send handoff notifications to this group instead of each number; the numbers above are mentioned in the message' => '各番号の代わりにこのグループにハンドオフ通知を送信します。上記の数字はメッセージに記載されています',
  'Last post to the group failed: ' => 'グループへの最後の投稿は失敗しました:',
  'Price list preview' => '価格表のプレビュー',
  'Enter an AI key and model first so the assistant can work.' => 'アシスタントが機能できるように、最初に AI キーとモデルを入力します。',
  'The assistant will not reply right now: ' => 'アシスタントは現在応答しません:',
  'WhatsApp assistant' => 'WhatsAppアシスタント',
  'Do not let the assistant share this content' => 'アシスタントにこのコンテンツを共有させないでください',
  'Corrected by staff member %1$s; #%2$d was opened instead.' => 'スタッフメンバー%1$sによって修正されました。 #%2$dが代わりにオープンされました。',
  'Donation #%1$d was cancelled and #%2$d opened instead.' => '寄付 #%1$dはキャンセルされ、代わりに #%2$dがオープンされました。',
  'Created by staff member %s via the WhatsApp assistant.' => 'WhatsApp アシスタントを介してスタッフ メンバー%sによって作成されました。',
  'Donation opened via staff member %1$s: %2$s (#%3$d)' => 'スタッフメンバー%1$s:%2$s(#%3$d) を通じて寄付が開始されました',
  'Your certificate 🌱' => 'あなたの証明書 🌱',
  'Staff member %1$s resent the certificate on WhatsApp: %2$s' => 'スタッフ メンバー%1$sが WhatsApp で証明書を再送信しました:%2$s',
  '✅ Your donor paid: *%1$s* · %2$s #%3$d' => '✅ あなたの寄付者が支払ったもの: *%1$s* ·%2$s#%3$d',
  '❌ Donation cancelled: *%1$s* · %2$s #%3$d' => '❌ 寄付がキャンセルされました: *%1$s* ·%2$s#%3$d',
  'Sticker' => 'ステッカー',
  'Poll' => '投票',
  'Unsupported message' => 'サポートされていないメッセージ',
  '{a} lines added, {d} lines removed' => '{a}行が追加され、{d}行が削除されました',
  'No AI key or model has been entered.' => 'AI キーまたはモデルが入力されていません。',
  'The assistant is off and does not reply to incoming messages.' => 'アシスタントはオフになっており、受信メッセージに応答しません。',
  'Test mode is on: the assistant only replies to test numbers.' => 'テスト モードがオンです。アシスタントはテスト番号にのみ応答します。',
  'Assistant activity summary' => 'アシスタント活動の概要',
  'Hide details' => '詳細を隠す',
  'Details' => '詳細',
  'Spend (USD)' => '支出 (USD)',
  'Questions answered' => '回答された質問',
  'People answered' => '人々は答えました',
  'People directed to donate' => '寄付をするように指示された人々',
  'Donation records created' => '寄付記録が作成されました',
  'Confirmed donations · {a}' => '確認された寄付 ·{a}',
  'Receipts read · ✓{a} ✕{b}' => '領収書の読み取り · ✓{a}✕{b}',
  'Memory tokens · {p} contacts' => 'メモリトークン・{p}コンタクト',
  'Opted out (blocklist)' => 'オプトアウト済み (ブロックリスト)',
  'Reminders sent' => '送信されたリマインダー',
