  'Messages (in order)' => 'メッセージ(順番に)',
  '{tur}, {birim} and {brand} can be used. If there are only customer messages, the assistant replies to each in turn. If you add assistant messages it becomes a continuation scenario: the written history is given as-is and the assistant replies only to the last customer message.' => '{tur}、{birim}および{brand}を使用できます。顧客メッセージのみがある場合、アシスタントはそれぞれのメッセージに順番に返信します。アシスタント メッセージを追加すると、継続シナリオになります。書き込まれた履歴はそのまま提供され、アシスタントは最後の顧客メッセージにのみ返信します。',
  'E.g. payment_info, cancel_donation, receipt_check. Tools disabled on this site are not checked.' => '例:支払い情報、寄付キャンセル、領収書チェック。このサイトで無効になっているツールはチェックされていません。',
  'Who is writing?' => '誰が書いていますか?',
  'Starting state (test)' => '開始状態(テスト)',
  'The scenario runs isolated like the test chat; what you select here exists only in this test. In a customer message, {kod} becomes the verification code from the test panel.' => 'シナリオはテスト チャットのように分離して実行されます。ここで選択したものは、このテスト内にのみ存在します。顧客メッセージでは、{kod}がテスト パネルからの確認コードになります。',
  'End state' => '終了状態',
  'When the conversation ends, the test state is checked (was a donation opened, canceled, a code sent…). Tools disabled on this site are not checked.' => '会話が終了すると、テスト状態がチェックされます (寄付が開かれたか、キャンセルされたか、コードが送信されたかなど)。このサイトで無効になっているツールはチェックされていません。',
  'Judge criterion' => '審査基準',
  'If empty, the judge is not called. Put quality expectations that cannot be written as rules here.' => '空の場合、ジャッジは呼ばれません。ルールとして記述できない品質への期待をここに記述します。',
  'Message written by the assistant' => 'アシスタントが書いたメッセージ',
  'Message written by the customer' => 'お客様が書いてくださったメッセージ',
  'Drag to reorder' => 'ドラッグして並べ替えます',
  'Change author' => '著者を変更する',
  'Delete message' => 'メッセージを削除する',
  'Customer message' => 'お客様からのメッセージ',
  'Assistant message' => 'アシスタントメッセージ',
  'Scenario saved ✓' => 'シナリオが保存されました ✓',
  'Edit scenario' => 'シナリオの編集',
  'E.g. Add one more message: the person does not want to give an email.' => '例:もう 1 つメッセージを追加します。その人は電子メールを送りたくないのです。',
  'E.g. The person asks about a sacrifice donation; the assistant hands off to the team without making anything up.' => '例:その人は犠牲の寄付について尋ねます。アシスタントは何も作り話せずにチームに引き継ぎます。',
  'Write' => '書く',
  'Edit scenario with AI' => 'AIによるシナリオ編集',
  'What should be tested?' => '何をテストする必要がありますか?',
  'Have the scenario written first.' => 'まずはシナリオを書いてもらいます。',
  'Writing…' => '執筆中...',
  'Rewrite' => 'リライト',
  'Documents' => '書類',
  'Benchmark' => 'ベンチマーク',
  '7 days' => '7日間',
  '30 days' => '30日',
  'Added to the instructions on every reply' => 'すべての返信の手順に追加',
  'Assistant reads it when needed' => 'アシスタントが必要に応じて読み上げます',
  '1h' => '1時間',
  'On' => 'オン',
  'Paused' => '一時停止中',
  'Out of scope' => '範囲外',
  'Approved' => '承認済み',
  'Skipped' => 'スキップされました',
  'Interrupted' => '中断されました',
  '%s ago' => '%s前',
  'Open settings' => '設定を開く',
  'Call Center · Setup' => 'コールセンター・セットアップ',
  'Call Center · WhatsApp' => 'コールセンター · WhatsApp',
  'Call Center · AI' => 'コールセンター・AI',
  'Database tables' => 'データベーステーブル',
  'Missing table: %s. Deactivate and reactivate the plugin.' => 'テーブルがありません:%s。プラグインを非アクティブ化し、再度アクティブ化します。',
  'Tables ready (schema %s).' => 'テーブルの準備ができました (スキーマ%s)。',
  'Schema update pending; it completes when you open a page in the admin panel.' => 'スキーマの更新は保留中です。管理パネルでページを開くと完了します。',
  'Media folder' => 'メディアフォルダー',
  'Cannot write to uploads/flx-chat; incoming photos, voice notes and documents cannot be saved. Check folder permissions.' => 'Uploads/flx-chat に書き込めません。受信した写真、音声メモ、ドキュメントは保存できません。フォルダーの権限を確認してください。',
  'Folder protection (.htaccess) missing; it is created with the first saved media.' => 'フォルダー保護 (.htaccess) がありません。最初に保存されたメディアを使用して作成されます。',
  'Writable and closed to the public.' => '書き込み可能で非公開です。',
  'PHP cURL' => 'PHPカール',
  'Available.' => '利用可能です。',
  'Missing; while the assistant prepares a reply the "typing…" indicator shows only briefly.' => '行方不明。アシスタントが応答を準備している間、「入力中...」インジケーターは短時間だけ表示されます。',
  'Users with the agent role: %d.' => 'エージェントの役割を持つユーザー:%d。',
  'No user has the agent role; only administrators can use it for now.' => 'エージェントの役割を持っているユーザーはいません。現時点では管理者のみが使用できます。',
  'Live panel updates' => 'ライブパネルの更新',
  'The chat screen has not been opened yet.' => 'まだチャット画面は開いていません。',
  'WhatsApp line' => 'WhatsAppライン',
  'No line added.' => '行は追加されていません。',
  '%s: connection details' => '%s: 接続の詳細',
  'Using Flux Mail connection: %s.' => 'Flux Mail 接続の使用:%s。',
  'Still using the old provider in Flux Certificates; move the connection to Flux Mail and select it here.' => 'Flux 証明書では依然として古いプロバイダーを使用しています。接続を Flux Mail に移動し、ここで選択します。',
  'Using the Evolution provider from Flux Certificates.' => 'Flux 証明書の Evolution プロバイダーを使用します。',
  'API URL, key and instance are entered in this plugin.' => 'このプラグインにはAPIのURL、キー、インスタンスを入力します。',
  '%s: line status' => '%s: 回線ステータス',
  'Phone connected (last seen %s).' => '電話が接続されました (最後に表示されたのは%s)。',
  'Not tested yet. Press "Test connection".' => 'まだテストされていません。 「接続テスト」を押します。',
  'Phone not connected (state: %1$s, %2$s). Reconnect with "Connect with QR".' => '電話が接続されていません (状態:%1$s、%2$s)。 「QRで接続」で再接続してください。',
  '%s: Evolution API version' => '%s: Evolution API バージョン',
  'Evolution API %s is in use. Replies to hidden-number (@lid) contacts may fail; update the server to 2.3 or later.' => 'Evolution API%sが使用されています。非表示の番号 (@lid) 連絡先への返信は失敗する場合があります。サーバーを 2.3 以降に更新します。',
  '%s: webhook (incoming messages)' => '%s: Webhook (受信メッセージ)',
  'No events have arrived from Evolution; incoming messages will not show in the panel. Press "Set up webhook".' => 'Evolution からイベントが到着していません。受信メッセージはパネルに表示されません。 「Webhookを設定する」を押します。',
  'Last event arrived %s. The line may just be quiet; send yourself a message or set up the webhook again to be sure.' => '最後のイベント%sが到着しました。回線が静かなだけかもしれません。自分にメッセージを送信するか、Webhook を再度設定して確認してください。',
  'Last event arrived %s.' => '最後のイベントが%sに到着しました。',
  'Flux Mail integration' => 'Flux メールの統合',
  'Active: WhatsApp connections are taken from Communication › Connections.' => 'アクティブ: WhatsApp 接続は、通信 › 接続から取得されます。',
  'Flux Mail is not active; connections are taken from Flux Certificates or from this plugin.' => 'Flux Mail はアクティブではありません。接続は Flux 証明書またはこのプラグインから取得されます。',
  'Flux Certificates integration' => 'Flux 証明書の統合',
  'Active: certificates can be created and sent from chats.' => 'アクティブ: チャットから証明書を作成および送信できます。',
  'Flux Certificates is not active; certificate actions in chats are off.' => 'Flux 証明書はアクティブではありません。チャットでの証明書アクションがオフになっています。',
  'Flux Donate integration' => 'Flux Donateの統合',
  'Active: donation records, receipt matching and the assistant are available from chats.' => 'アクティブ: 寄付記録、領収書の照合、アシスタントはチャットから利用できます。',
  'Flux Donate is not active; donation records, receipt matching and the donation assistant are off.' => 'Flux Donate はアクティブではありません。寄付記録、領収書の照合、寄付アシスタントがオフになっています。',
  'The Flux AI & MCP plugin is not installed; AI features (suggestions, assistant, receipt reading, voice messages, summaries) are off. Install Flux AI and enter the key there.' => 'Flux AI および MCP プラグインはインストールされていません。 AI 機能 (提案、アシスタント、レシート読み上げ、音声メッセージ、要約) はオフになっています。 Flux AI をインストールし、そこにキーを入力します。',
  'No key has been entered in Flux AI; message suggestions and the assistant are off.' => 'Flux AI にキーが入力されていません。メッセージの提案とアシスタントはオフになっています。',
  'Key saved but no model selected.' => 'キーは保存されましたが、モデルが選択されていません。',
  'No provider key has been entered in Flux AI for the selected model (%s).' => '選択したモデル (%s) の Flux AI にプロバイダー キーが入力されていません。',
  'Key saved, model: %s. Use "Test connection" for a live check.' => 'キーが保存されました、モデル:%s。ライブチェックには「接続テスト」を使用します。',
  'Donation assistant' => '寄付アシスタント',
  'Off.' => 'オフ。',
  'AI key or model is missing.' => 'AI キーまたはモデルがありません。',
  'On but not replying: ' => 'オンだが応答がない:',
  'On. Donation types offered: %s.' => 'オン。提供される寄付の種類:%s。',
  '%s does not support tools; choose a tool-capable model for the assistant.' => '%sはツールをサポートしていません。アシスタントにはツール対応モデルを選択してください。',
  'Receipt reading model' => 'レシート読み取りモデル',
  '%s cannot read images; the receipt pre-check will not work. Choose an image-capable receipt reading model.' => '%sはイメージを読み取れません。領収書の事前チェックは機能しません。画像対応のレシート読み取りモデルを選択してください。',
  'Assistant payment details' => 'アシスタントの支払い詳細',
  'Recipient name and IBAN set.' => '受信者名とIBANが設定されています。',
  'Recipient name or IBAN missing; bank details cannot be sent after confirmation.' => '受信者名または IBAN がありません。確認後に銀行口座情報を送信することはできません。',
  'Donation page link' => '寄付ページへのリンク',
  'Donation page not found; the assistant will not send a link.' => '寄付ページが見つかりません。アシスタントはリンクを送信しません。',
  'Background requests' => 'バックグラウンドリクエスト',
  'The site could not send a background request to itself (%1$s: %2$s). Queued replies and the benchmark may move slowly; a security plugin or the server firewall may be blocking /wp-json/flx-chat/ requests.' => 'サイトはバックグラウンドリクエストをそれ自体に送信できませんでした (%1$s:%2$s)。応答がキューに入れられ、ベンチマークの動きが遅くなる可能性があります。セキュリティ プラグインまたはサーバー ファイアウォールが /wp-json/flx-chat/ リクエストをブロックしている可能性があります。',
  'error' => 'エラー',
  'warning' => '警告',
  'ok' => 'わかりました',
  'Your {marka} verification code: {kod}' => '{marka}確認コード:{kod}',
  'The code is valid for {dk} minutes. Type it in your WhatsApp chat with us. If you did not ask for it, ignore this message.' => 'コードは{dk}分間有効です。 WhatsApp チャットにそれを入力してください。要求していない場合は、このメッセージを無視してください。',
  'Something went wrong; our team will contact you as soon as possible 🌱 Meanwhile, feel free to ask anything else.' => '何か問題が発生しました。私たちのチームができるだけ早くご連絡いたします 🌱 その他、何かございましたらお気軽にご質問ください。',
  'Verification attempt failed (%1$d/%2$d): %3$s' => '検証の試行が失敗しました (%1$d/%2$d):%3$s',
  'The person wanted to see their records but could not be verified; someone from the team should get in touch' => 'その人は自分の記録を見たいと思っていましたが、確認することができませんでした。チームの誰かが連絡する必要があります',
  'e-mail could not be sent (check Flux Mail › SMTP settings)' => '電子メールを送信できませんでした (Flux Mail › SMTP 設定を確認してください)',
  'The assistant sent a verification code for %1$s (%2$s).' => 'アシスタントは%1$s(%2$s) の確認コードを送信しました。',
  'code expired' => 'コードの有効期限が切れました',
  'wrong code' => '間違ったコード',
  'The person verified the code for %s; it is added to their record lookups.' => 'その人は%sのコードを検証しました。それはレコード検索に追加されます。',
  'Claude models cannot read audio; choose an audio-capable OpenRouter model in Settings › AI › Voice message model.' => 'クロード モデルは音声を読み取ることができません。 [設定] › AI › 音声メッセージ モデルでオーディオ対応の OpenRouter モデルを選択します。',
  'The audio could not be transcribed.' => '音声を転写できませんでした。',
  'The audio file could not be read.' => '音声ファイルを読み取れませんでした。',
  'Voice message (%1$s) transcribed: %2$s' => '音声メッセージ (%1$s) 文字起こし:%2$s',
  'Voice message (%1$s) could not be processed: %2$s' => '音声メッセージ (%1$s) を処理できませんでした:%2$s',
  'This action is not available on an official WhatsApp Cloud API line.' => 'このアクションは、公式の WhatsApp Cloud API ラインでは利用できません。',
  'WhatsApp 24-hour rule: the contact has not written in the last 24 hours, so the Cloud API will not send a free-form message; only an approved template can be sent. Try again once they write.' => 'WhatsApp の 24 時間ルール: 連絡先は過去 24 時間にメッセージを書いていないため、Cloud API は自由形式のメッセージを送信しません。承認されたテンプレートのみを送信できます。彼らが書いたら、もう一度試してください。',
  'A Cloud API line needs Flux Mail 1.10.0 or later.' => 'Cloud API ラインには Flux Mail 1.10.0 以降が必要です。',
  'The Cloud API cannot send to this address (hidden number or group).' => 'Cloud API は、このアドレス (非表示の番号またはグループ) に送信できません。',
  'Could not reach the Cloud API account (İletişim › Connections).' => 'Cloud API アカウント (İletişim › 接続) にアクセスできませんでした。',
  'A Cloud API line has no QR code; the account is set up in İletişim › Connections.' => 'Cloud API ラインには QR コードがありません。アカウントは İletişim › 接続 で設定されます。',
  'The file could not be prepared.' => 'ファイルを準備できませんでした。',
  'Flux AI has no image support.' => 'Flux AI は画像をサポートしていません。',
  'The image could not be rendered.' => '画像をレンダリングできませんでした。',
  'The assistant\'s image could not be sent: ' => 'アシスタントの画像を送信できませんでした:',
  'Hello {first_name}, we have created your donation record: {donation}, total {amount}.' . chr(10) . '' . chr(10) . '{bank}' . chr(10) . '' . chr(10) . 'After paying, you can send the receipt here. Thank you.' => '{first_name}さん、こんにちは。寄付記録{donation}、合計{amount}が作成されました。{bank}お支払い後、こちらから領収書をお送りください。ありがとう。',
  'Hello {first_name}, your donation has been recorded: {donation}, total {amount}.' . chr(10) . '' . chr(10) . 'Thank you for your support.' => 'こんにちは{first_name}さん、あなたの寄付が記録されました:{donation}、合計{amount}。' . chr(10) . '' . chr(10) . 'ご支援ありがとうございます。',
  'The plugin that would run this scenario is inactive.' => 'このシナリオを実行するプラグインは非アクティブです。',
  'This user is not allowed to use the staff tools.' => 'このユーザーはスタッフツールを使用できません。',
  '%1$s linked this chat to staff member %2$s' => '%1$sがこのチャットをスタッフ メンバー%2$sにリンクしました',
  '%s removed the staff link of this chat' => '%sがこのチャットのスタッフ リンクを削除しました',
  'Chat linked to staff member' => 'スタッフメンバーにリンクされたチャット',
  'Staff link removed' => 'スタッフリンクが削除されました',
  '— Not staff —' => '— スタッフではありません —',
  'WhatsApp hides this person\'s number, so the assistant cannot recognise staff by number. If this person is on your team, link them here and the assistant opens the staff tools.' => 'WhatsApp はこの人の番号を非表示にするため、アシスタントは番号でスタッフを認識できません。この人があなたのチームに属している場合は、ここでリンクすると、アシスタントがスタッフ ツールを開きます。',
  'The assistant recognises staff by the number in their Flux Roles profile. If the number does not match, you can link them here; in a chat with a known number the number comes first.' => 'アシスタントは、Flux ロール プロファイル内の番号によってスタッフを認識します。番号が一致しない場合は、ここでリンクできます。既知の番号とのチャットでは、その番号が最初に来ます。',
  'This channel is not available right now.' => 'このチャンネルは現在利用できません。',
  'Site chat' => 'サイトチャット',
  'All messages from WhatsApp, site chat and other channels appear here live. Pick a chat on the left.' => 'WhatsApp、サイトチャット、その他のチャネルからのすべてのメッセージがここにライブで表示されます。左側にあるチャットを選択します。',
  '[[\'WhatsApp (Evolution API) call center: see live incoming and outgoing messages, start new chat, canned replies, tags, assignment, internal notes, auto-replies; Donation (Flux Donate) and certificate (Flux Certificates) registration from chat, receipt matching. Artificial intelligence response suggestion and automatic donation assistant with OpenRouter.\', \'tr\']]' => 'WhatsApp (Evolution API) コールセンター: ライブの送受信メッセージの表示、新しいチャットの開始、返信定型文、タグ、割り当て、社内メモ、自動返信。チャットからの寄付(Flux Donate)と証明書(Flux Certificates)の登録、レシート照合。 OpenRouter による人工知能の応答提案と自動寄付アシスタント。',
  'Çağrı Merkezi' => 'コールセンター',
  'Sohbetler' => 'チャット',
  'AI asistan' => 'AIアシスタント',
  'Çağrı Merkezi Ayarları' => 'コールセンターの設定',
  'Ayarlar' => '設定',
  'Çağrı Merkezi için JavaScript gerekli.' => 'コールセンターにはJavaScriptが必要です。',
  'Bu sayfaya erişim yetkiniz yok.' => 'このページにアクセスする権限がありません。',
  'Asistanın yazıştığı sohbetleri izleyin, talimatını ve belgelerini düzenleyin, değişiklikleri yayına almadan önce test edin.' => 'アシスタントが処理するチャットを監視し、その指示とドキュメントを編集し、公開する前に変更をテストします。',
  'Asistan ayarları' => 'アシスタントの設定',
  'Bu sayfa için JavaScript gerekli.' => 'このページにはJavaScriptが必要です。',
  'Kapalı' => '閉店',
  'Açık, 5 dakika' => 'オン、5 分',
  'Açık, 1 saat' => 'オン、1時間',
  'Yapay zekâ için Flux AI & MCP eklentisi gerekli; kurup etkinleştirin ve Flux AI & MCP › Ayarlar\'a anahtarı girin.' => 'AI には Flux AI および MCP プラグインが必要です。インストールしてアクティベートし、Flux AI & MCP › 設定にキーを入力します。',
  'Yapay zekâ modeli seçilmemiş.' => 'AI モデルが選択されていません。',
  'Flux AI\'de Anthropic (Claude) anahtarı girilmemiş.' => 'Flux AI に Anthropic (Claude) キーが入力されていません。',
  'Flux AI\'de OpenRouter anahtarı girilmemiş.' => 'Flux AI に OpenRouter キーが入力されていません。',
  'Model listesi için Flux AI & MCP eklentisi gerekli.' => 'モデル リストには Flux AI および MCP プラグインが必要です。',
  'Flux Chat: yapay zekâ özellikleri (öneri, asistan, dekont okuma, sesli mesaj, özet) için Flux AI & MCP eklentisi gerekli. Kurup etkinleştirin; Çağrı Merkezi\'nde kayıtlı anahtarlar oraya kendiliğinden aktarılır.' => 'Flux コールセンター: AI 機能 (提案、アシスタント、領収書の読み取り、音声メッセージ、概要) には、Flux AI および MCP プラグインが必要です。インストールしてアクティブ化します。コールセンターに保存されたキーは自動的にそこに移動されます。',
  'Flux Chat: %s anahtarı Flux AI\'de farklı bir anahtar olarak zaten kayıtlı; Flux AI\'deki kullanılıyor. Çağrı Merkezi\'ndeki eski anahtar aktarılmadı ve artık kullanılmıyor.' => 'Flux コールセンター: 別の%sキーがすでに Flux AI に保存されており、使用されています。古いコールセンター キーは移動されず、使用されなくなりました。',
  'Flux Chat: yapay zekâ anahtarları Flux AI\'ye aktarıldı. Bundan sonra anahtar, harcama sınırı ve kayıtlar Flux AI\'den yönetilir; model seçimleri Çağrı Merkezi\'nde kalır.' => 'Flux コールセンター: AI キーが Flux AI に移動されました。今後、キー、支出制限、ログは Flux AI で管理されます。モデルの選択はコールセンターに残ります。',
  'Flux Donate eklentisi etkin değil; asistan bağış türlerini ve fiyatları oradan alır.' => 'Flux Donate プラグインはアクティブではありません。アシスタントはそこから寄付の種類と価格を取得します。',
