  'Dekontunuzu aldık, teşekkür ederiz 🌱 Ödemenizle ilgili size en kısa zamanda dönüş yapacağız.' => '領収書を受け取りました、ありがとうございます 🌱 お支払いについてはできるだけ早くご連絡いたします。',
  'Dekontunuzu aldık, teşekkür ederiz 🌱 Bağışınız onaylandı.' => '領収書を受け取りました、ありがとうございます 🌱 寄付が確認されました。',
  'Bu dekontu daha önce almıştık, teşekkür ederiz 🌱 Ödemenizle ilgili size en kısa zamanda dönüş yapacağız.' => 'この領収書はすでに受領しております。ありがとうございます 🌱 お支払いについてはできるだけ早くご連絡いたします。',
  'Bu dekont daha önce sistemimize yüklenmiş görünüyor. Aynı dekont ikinci bir bağış için kullanılamaz. Farklı bir ödeme yaptıysanız o ödemenin dekontunu gönderebilirsiniz; ekibimiz de ayrıca kontrol edecek.' => 'この領収書は以前に当社のシステムにアップロードされたものと思われます。同じ領収書を二度目の寄付に使用することはできません。別の支払いをした場合は、その領収書をお送りください。私たちのチームもチェックします。',
  'Dekontunuzu aldık. Dekonttaki tutar (%1$s) bağışınızın tutarıyla (%2$s) uyuşmuyor gibi görünüyor. Kontrol edebilir misiniz? Farklı bir ödeme yaptıysanız buradan yazabilirsiniz, ekibimiz de ayrıca bakacak.' => '領収書を受け取りました。記載されている金額 (%1$s) が寄付金額 (%2$s) と一致していないようです。確認してもらえますか?別の支払いをした場合は、ここに記入できます。私たちのチームも検討します。',
  'Dekontunuzu aldık, ancak dekonttaki alıcı derneğimiz değil gibi görünüyor. Bağışlarımız yalnız "%s" adına açılmış hesabımıza yapılır. Kontrol edebilir misiniz? Ekibimiz de ayrıca bakacak.' => '領収書を受け取りましたが、その受取人は当協会ではないようです。寄付は「%s」という名前のアカウントにのみ行われます。確認してもらえますか?私たちのチームも検討します。',
  'Dekontunuzu aldık, ancak dekonttaki alıcı bilgisi bizim hesabımızla eşleşmiyor gibi görünüyor. Kontrol edebilir misiniz? Ekibimiz de ayrıca bakacak.' => '領収書を受け取りましたが、領収書に記載されている受取人が私たちのアカウントと一致していないようです。確認してもらえますか?私たちのチームも検討します。',
  'Gönderdiğiniz dosya bir ödeme dekontuna benzemiyor. Ödemeyi yaptıysanız dekontu ya da ödeme ekranının görüntüsünü buradan gönderebilirsiniz.' => '送信されたファイルは支払い領収書のようには見えません。支払いを行った場合は、領収書または支払い画面のスクリーンショットをここに送信できます。',
