  'Rapor şimdi tüm alıcılara gönderilsin mi?' => '今すぐすべての受信者にレポートを送信しますか?',
  'Şimdi herkese gönder' => '今すぐ全員に送信',
  'Bu rapor silinsin mi?' => 'このレポートを削除しますか?',
  '+ Yeni rapor' => '+ 新しいレポート',
  'Alıcının numarası Kullanıcılar › Profil › WhatsApp numarası alanından gelir; yetkiler Kullanıcılar › Roller ve erişim sayfasından (rapor alabilir, genel raporu görebilir, raporları yönetir). Rapor seçilen saatte gider; sunucu zamanlayıcısı yoksa sitenin ilk ziyaretinde ya da sohbet panelinde gönderilir.' => '受信者の番号は、ユーザー › プロフィール › WhatsApp 番号から取得されます。ユーザーからの権限 › 役割とアクセス (レポートの受信、レポート全体の表示、レポートの管理)。レポートは選択した時間に送信されます。サーバー スケジューラを使用しないと、次回のサイト訪問時またはチャット パネルの使用時に送信されます。',
  'Geçersiz telefon numarası.' => '電話番号が無効です。',
  'Önce Ayarlar › Bağlantılar bölümünden bir WhatsApp bağlantısı ekleyin.' => 'まず、[設定] › [接続] で WhatsApp 接続を追加します。',
