  'Bu dosya türü gönderilemez.' => 'この種類のファイルは送信できません。',
  'Dosya yüklenemedi.' => 'ファイルをアップロードできませんでした。',
  'Bu mesaj yeniden gönderilemez.' => 'このメッセージは再送信できません。',
  'Bu mesaja tepki verilemez.' => 'このメッセージには反応できません。',
  'Yalnız kendi notlarınızı silebilirsiniz.' => '削除できるのは自分のメモのみです。',
  'Cevap metni boş olamaz.' => '返信テキストを空にすることはできません。',
  'Bağlantı bulunamadı. Önce ayarları kaydedin.' => '接続が見つかりません。まず設定を保存します。',
  'Mesaj yalnız görsel kodundan oluşuyordu; gönderilmedi.' => 'メッセージは画像コードのみでした。送信されませんでした。',
  'Bu kişi kara listede; mesaj gönderilmez. Kara listeden çıkarınca yeniden yazabilirsiniz.' => 'この連絡先はブロックリストに登録されています。メッセージは送信されません。再度書き込むには、ブロックリストから削除してください。',
  'Mesaj kaydedilemedi.' => 'メッセージを保存できませんでした。',
  'Bu kişi WhatsApp gizli numarasıyla (@lid) yazıyor ve Evolution API (sürüm %s) bu adrese gönderemedi. Evolution API sunucusunu 2.3 veya üstüne güncelleyin; kişinin gerçek numarası gelirse eklenti oraya gönderir.' => 'この連絡先は非表示の WhatsApp 番号 (@lid) から書き込みを行っており、Evolution API (バージョン%s) はこのアドレスに送信できませんでした。 Evolution API サーバーを 2.3 以降に更新します。連絡先の実番号が到着すると、プラグインはそこに送信します。',
  'Bu kişi WhatsApp gizli numarasıyla (@lid) yazıyor ve Evolution API bu adrese gönderemedi. Evolution API sunucusunu 2.3 veya üstüne güncelleyin; kişinin gerçek numarası gelirse eklenti oraya gönderir.' => 'この連絡先は非表示の WhatsApp 番号 (@lid) から書き込んでいるため、Evolution API はこのアドレスに送信できませんでした。 Evolution API サーバーを 2.3 以降に更新します。連絡先の実番号が到着すると、プラグインはそこに送信します。',
  'WhatsApp bağlantısı yok.' => 'WhatsApp 接続がありません。',
  'Bağlı ✓' => '接続済み ✓',
  'Bağlı değil (durum: %s). QR ile bağlayın.' => '接続されていません (状態:%s)。 QRで接続します。',
  'Webhook bu siteye ayarlı ✓' => 'Webhook はこのサイトを指します ✓',
  'Evolution API sürümü: %s' => 'Evolution API バージョン:%s',
  '(eski: gizli numaralı (@lid) kişilere cevap gidemeyebilir, 2.3 veya üstüne güncelleyin)' => '(旧: 非表示の番号 (@lid) 連絡先への返信が失敗する場合がある。2.3 以降に更新してください)',
  'Webhook bu siteye ayarlı değil. "Webhook\'u kur" düğmesine basın.' => 'Webhook はこのサイトを指していません。 「Webhookを設定する」を押します。',
  'Webhook kuruldu ✓ Artık gelen mesajlar buraya düşer.' => 'Webhook の設定 ✓ 受信メッセージがここに到着します。',
  'Son sohbetler içe aktarılıyor, bu biraz sürebilir…' => '最近のチャットをインポートしています。これにはしばらく時間がかかる場合があります...',
  'Evolution\'da kayıtlı mesaj: %s' => 'Evolution に保存されたメッセージ:%s',
  'Evolution mesajları kaydetmiyor, bu yüzden eski mesajlar gelemez. Evolution sunucusunda DATABASE_SAVE_DATA_NEW_MESSAGE ve DATABASE_SAVE_DATA_HISTORIC değerlerini true yapın; eski konuşmalar için hattı QR ile yeniden bağlarken instance ayarında "Sync full history" açık olsun.' => 'Evolution はメッセージを保存しないため、古いメッセージをロードすることはできません。 Evolution サーバーで、DATABASE_SAVE_DATA_NEW_MESSAGE と DATABASE_SAVE_DATA_HISTORIC を true に設定します。古い会話の場合は、QR で回線を再接続するときにインスタンス設定で [全履歴を同期] をオンのままにします。',
  '%1$s sohbet, %2$s mesaj içe aktarıldı ✓' => '%1$sチャット、%2$sメッセージのインポート ✓',
  'WhatsApp › Bağlı cihazlar › Cihaz bağla ile bu kodu okutun.' => 'WhatsApp › リンクされたデバイス › デバイスをリンクしてこのコードをスキャンします。',
  'Eşleştirme kodu:' => 'ペアリングコード:',
  'Bu hat zaten bağlı ✓' => 'この回線はすでに接続されています ✓',
  'Önce ayarları kaydedin.' => 'まず設定を保存します。',
  'Hata:' => 'エラー:',
  'Bu bağlantı silinsin mi? Sohbet geçmişi silinmez.' => 'この接続を削除しますか?チャット履歴は保存されます。',
  'Yapay zekâya soruluyor…' => 'AIに聞いてみると...',
  'Çalışıyor ✓ (%2$s ms): %1$s' => '動作中 ✓ (%2$sミリ秒):%1$s',
  'Önce anahtarı ve modeli kaydedin.' => 'まずキーとモデルを保存します。',
  'Bağlantılar' => '接続',
  'Otomatik yanıtlar' => '自動返信',
  'Yapay zekâ ve asistan' => 'AIとアシスタント',
  'Sistem kontrolü' => 'システムチェック',
  'WhatsApp hattınızı bağlayın, otomatik yanıtları ve etiketleri yönetin.' => 'WhatsApp 回線に接続し、自動返信とラベルを管理します。',
  'Sohbetleri aç' => 'オープンチャット',
  'Ayarlar kaydedildi.' => '設定が保存されました。',
  'Çağrı Merkezi\'nin çalışması için gereken bağlantılar ve ayarlar. Kayıtlı durumlar gösterilir; canlı deneme için ilgili sekmedeki "test et" düğmelerini kullanın. Aynı kontroller temanın sistem kontrolü ekranında diğer eklentilerle birlikte de görünür.' => 'コールセンターに必要な接続と設定。保存されたステータスが表示されます。ライブチェックには各タブの「テスト」ボタンを使用してください。テーマのシステムチェック画面では、他のプラグインにも同じチェックが表示されます。',
  'WhatsApp hatları' => 'WhatsApp ライン',
  'Mesajlar Evolution API üzerinden gönderilir ve alınır. WhatsApp bağlantıları Flux Mail\'de yönetilir; burada hangisinin kullanılacağını seçin. Adres ve API key orada kalır, değişince burada ayrıca güncellemek gerekmez.' => 'メッセージはEvolution APIを通じて送受信されます。 WhatsApp 接続は Flux Mail で管理されます。ここでどれを使用するかを選択します。 URL と API キーはそこに残るため、変更されたときにここで更新する必要はありません。',
  'İletişim › Bağlantılar' => 'コミュニケーション › 接続',
  'Mesajlar Evolution API üzerinden gönderilir ve alınır. Flux Certificates eklentisinde Evolution sağlayıcısı tanımlıysa aynı bağlantıyı seçebilirsiniz; adres ve API key orada kalır.' => 'メッセージはEvolution APIを介して送受信されます。 Evolution プロバイダーが Flux 証明書で設定されている場合は、同じ接続を選択できます。 URL と API キーはそこに残ります。',
  'Hat ekle' => '行を追加',
  'Kurulum adımları' => 'セットアップ手順',
  'Hattı ekleyip kaydedin.' => '行を追加して保存します。',
  '"Bağlantıyı test et" ile Evolution\'a ulaşıldığını görün. Hat bağlı değilse "QR ile bağla" deyip telefondan okutun.' => '「テスト接続」を使用して、Evolution に到達できることを確認します。回線がリンクされていない場合は、「QRで接続」を選択し、携帯電話からスキャンしてください。',
  '"Webhook\'u kur" düğmesine basın. Gelen mesajlar, telefondan ve Flux Certificates\'dan gönderilenler canlı olarak buraya düşer.' => '「Webhookを設定する」を押します。受信メッセージ、電話や Flux 証明書から送信されたメッセージは、ここにライブで表示されます。',
  'İsterseniz "Son sohbetleri içe aktar" ile geçmiş mesajları getirin.' => '必要に応じて、「最近のチャットをインポート」を使用して過去のメッセージを取り込みます。',
  'bağlı' => '接続されています',
  'bağlanıyor' => '接続する',
  'bağlı değil' => '接続されていません',
  'sunucuda yok' => 'サーバー上にない',
  'ulaşılamıyor' => '到達不可能な',
  'Flux Mail bağlantısı: %s' => 'Flux メール接続:%s',
  'Flux Mail bağlantısı #%d (bulunamadı ya da kapalı)' => 'Flux Mail 接続 #%d(見つからないか無効になっています)',
  'Flux Certificates sağlayıcısını kullan: %s' => 'Flux 証明書プロバイダーを使用:%s',
  'Ayrı Evolution API bilgisi gir' => 'Evolution API の詳細を個別に入力します',
  'Hat adı (ör. Ana hat)' => '路線名(例:幹線)',
  'Bağlantı bilgisi' => '接続の詳細',
  'API adresi' => 'API URL',
  'Instance adı' => 'インスタンス名',
  '•••••••• (kayıtlı; değiştirmek için yazın)' => '•••••••(保存済み、変更するタイプ)',
  'Webhook adresi' => 'Webhook URL',
