  'QR ile bağla' => 'QRでつながる',
  'QR, durum ve hesaplar: İletişim › Bağlantılar' => 'QR、ステータス、アカウント: コミュニケーション › 接続',
  'Webhook\'u kur' => 'Webhook を設定する',
  'Son sohbetleri içe aktar' => '最近のチャットをインポートする',
  'Kaydettikten sonra webhook adresi ve test düğmeleri görünür.' => '保存すると、Webhook URL とテスト ボタンが表示されます。',
