  'Panel başlığı' => 'パネルタイトル',
  'Boş bırakılırsa site adı. {brand} değişkeni de bunu kullanır.' => '空の場合はサイト名。{brand}変数もこれを使用します。',
  'Vurgu rengi' => 'アクセントカラー',
  'Çalışma şekli' => '行動',
  'Sohbet açılınca karşı tarafa okundu bilgisi (mavi tik) gönder' => 'チャットを開いたときに開封確認 (青いチェックマーク) を送信します',
  'Mesajın başına temsilci adını ekle (*Ad:*)' => 'メッセージの前にエージェント名を付けます (*Name:*)',
  'Temsilciler yalnız kendine atanan ve atanmamış sohbetleri görsün (yöneticiler hepsini görür)' => 'エージェントには、自分に割り当てられたチャットと割り当てられていないチャットのみが表示されます (管理者にはすべてが表示されます)',
  'WhatsApp grup mesajlarını da göster' => 'WhatsApp グループメッセージも表示します',
  'Yeni arayüz (deneysel): Sohbetler sayfası masaüstü ve mobil uygulamayla aynı ekranla açılır' => '新しいインターフェイス (実験的): デスクトップおよびモバイル アプリと同じ画面でチャット ページが開きます。',
  'Canlı güncelleme sıklığı (sn)' => 'ライブアップデート間隔(秒)',
  'Açık sekmede bu aralıkla yeni mesaj kontrol edilir (önerilen 10). Sekme arka plandayken dakikada bir, hata olursa giderek seyrekleşir.' => '開いているタブは、この間隔 (推奨 10) で新しいメッセージをチェックします。バックグラウンド タブでは、1 分に 1 回チェックされますが、エラー後は頻度が低くなります。',
  'Temsilciler' => 'エージェント',
  'Bir kullanıcıya %s rolü verin; yalnız sohbet ekranını görür, ayarlara giremez. Yöneticiler her zaman erişir.' => 'ユーザーに%sロールを与えます。チャット画面のみが表示され、設定を開くことはできません。管理者は常にアクセスできます。',
  'Yeni kullanıcı ekle' => '新しいユーザーを追加',
  'Veri' => 'データ',
  'Eklenti silinirken tüm sohbetleri, mesajları ve medya dosyalarını da sil' => 'プラグインを削除すると、すべてのチャット、メッセージ、メディア ファイルも削除されます。',
  'Medya dosyaları wp-content/uploads/flx-chat klasöründe, dışarıdan erişime kapalı tutulur. Site taşınırken uploads ile birlikte gider.' => 'メディア ファイルは wp-content/uploads/flx-chat に保管され、外部からのアクセスは禁止されています。サイトが移行されると、アップロードとともに移動します。',
  'Pzt' => '月',
  'Sal' => '火',
  'Çar' => '水',
  'Per' => '木',
  'Cum' => '金',
  'Cmt' => '土',
  'Paz' => '太陽',
  'Karşılama mesajı' => 'ウェルカムメッセージ',
  'Bize ilk kez yazan kişiye otomatik gönder' => '初めてメールを送信する人に自動的に送信します',
  'Mesai dışı yanıtı' => 'アウェイメッセージ',
  'Mesai saatleri dışında gelen mesajlara otomatik yanıt ver' => '営業時間外に受信したメッセージには自動返信します',
  'Mesai günleri' => '営業日',
  'Başlangıç' => 'スタート',
  'Bitiş' => '終了',
  'Aynı kişiye en fazla (saatte bir)' => '連絡先ごとに最大 1 回(時間ごと)',
  'Saat dilimi: %1$s. Şu an: %2$s.' => 'タイムゾーン:%1$s。現在:%2$s。',
  'mesai içi' => '営業時間内',
  'mesai dışı' => '営業時間外',
  'Metinlerde {first_name}, {name}, {brand}, {site}, {date} değişkenleri kullanılabilir.' => '{first_name}、{name}、{brand}、{site}、{date}変数はテキスト内で使用できます。',
  'Sohbet etiketleri' => 'チャットラベル',
  'Sohbetleri etiketleyip listede filtreleyin (ör. Bağış, Şikâyet, Takip).' => 'チャットにラベルを付けてリストをフィルタリングします (寄付、苦情、フォローアップなど)。',
  'Etiket ekle' => 'ラベルを追加する',
  'Etiket adı' => 'レーベル名',
  'Sohbetten kayıt oluşturma' => 'チャットからレコードを作成する',
  'Sohbet başlığındaki düğmelerle bağış kaydı (Flux Donate) ve sertifika (Flux Certificates) oluşturulur, gelen dekont kayıtla eşleştirilir. Eklenti kurulu değilse ilgili düğme görünmez.' => 'チャット ヘッダーのボタンにより寄付レコード (Flux Donate) と証明書 (Flux Certificates) が作成され、受信した領収書がレコードと照合されます。プラグインがインストールされていない場合、そのボタンは非表示になります。',
  'Temsilciler bağış kaydı oluşturabilsin ve dekont eşleştirebilsin' => 'エージェントは寄付記録を作成し、領収書を照合できます',
  'Temsilciler sertifika oluşturup gönderebilsin' => 'エージェントは証明書を作成して送信できます',
  'Mesaj kutusunun üstünde hazır cevap baloncuklarını göster' => 'メッセージ ボックスの上にクイック返信バブルを表示する',
  'Bağış mesajları' => '寄付メッセージ',
  'Kayıt oluşturulunca kişiye gönderilecek hazır metinler (gönderimden önce düzenlenebilir). Boş bırakılırsa varsayılan metin kullanılır.' => 'レコードの作成時にその人に送信される準備完了のテキスト (送信前に編集可能)。空のままにすると、デフォルトのテキストが使用されます。',
  'Ödeme bekleniyor (havale sözü)' => '支払い待ち(約束された送金)',
  'Bağış alındı' => '寄付金を受け取りました',
  'Dekont onaylandı' => '受領確認済み',
  'Banka bilgisi ({bank})' => '銀行詳細 ({bank})',
  'Alıcı adı, banka, IBAN' => '受取人の名前、銀行、IBAN',
  'Boşsa WooCommerce › Ödemeler › Havale / EFT ayarındaki hesap kullanılır.' => '空の場合、WooCommerce › 支払い › 銀行振込のアカウントが使用されます。',
  'Değişkenler: {first_name}, {name}, {donation}, {amount}, {quantity}, {bank}, {certificate_link}, {agent}, {brand}, {date}.' => '変数:{first_name}、{name}、{donation}、{amount}、{quantity}、{bank}、{certificate_link}、{agent}、{brand}、{date}。',
  'Yapay zekâ bağlantısı' => 'AI接続',
  'Anahtarlar, prompt önbelleği, harcama sınırı ve kullanım kayıtları Flux AI & MCP eklentisinden gelir; Çağrı Merkezi\'nin tüm yapay zekâ istekleri oradan geçer. Model seçimleri burada kalır; alanlar boşsa Flux AI\'de bu eklentiye seçilen model (ya da varsayılan) kullanılır.' => 'キー、プロンプト キャッシュ、支出制限、使用ログは Flux AI および MCP プラグインから取得されます。コールセンターの AI リクエストはすべてそれを通過します。モデルの選択はここに留まります。フィールドが空の場合、Flux AI でこのプラグイン用に選択されたモデル (またはデフォルト) が使用されます。',
  'Flux AI ayarlarını aç' => 'Flux AI 設定を開く',
  'Yapay zekâ için Flux AI & MCP eklentisi gerekli. Kurup etkinleştirin ve Flux AI & MCP › Ayarlar\'a OpenRouter ve/veya Anthropic anahtarını girin. O zamana kadar öneri, asistan, dekont okuma, sesli mesaj ve özet kapalıdır.' => 'AI には Flux AI および MCP プラグインが必要です。インストールしてアクティベートし、Flux AI と MCP › 設定に OpenRouter キーや Anthropic キーを入力します。それまでは、提案、アシスタント、レシートの読み上げ、音声メッセージ、概要はオフになります。',
  'Yaratıcılık (0–1)' => '創造性 (0–1)',
  'Düşük değer daha tutarlı, yüksek değer daha serbest cevap verir. Önerilen 0,4.' => '値が低いほど一貫性のある応答が得られ、値が高いほど自由な応答が得られます。 0.4をお勧めします。',
  'Model (öneriler için)' => 'モデル(提案用)',
  'Asistan modeli (isteğe bağlı)' => 'アシスタントモデル(オプション)',
  'Yukarıdaki model' => '上記のモデル',
  'Yalnız araç (tools) destekleyen modeller listelenir.' => 'ツールをサポートするモデルのみがリストされています。',
  'Dekont okuma modeli (isteğe bağlı)' => 'レシート読み取りモデル(オプション)',
  'Seçilen model görsel okuyamıyorsa görsel okuyan ucuz bir modele kendiliğinden geçilir.' => '選択したモデルが画像を読み取れない場合は、安価なビジョンモデルが自動的に使用されます。',
  'Bu ay (%1$s): %2$s istek, %3$s token, yaklaşık $%4$s.' => '今月 (%1$s):%2$sリクエスト、%3$sトークン、約 $%4$s。',
  'Cevap önerisi' => '返信の提案',
  'Mesaj kutusunun üstünde, konuşmaya göre sıradaki mesaj önerilir. Temsilci "Gönder" der ya da "Düzenle" ile kutuya alıp değiştirir. Öneri asla kendiliğinden gönderilmez.' => 'メッセージ ボックスの上に、会話から次のメッセージが提案されます。エージェントは「送信」をクリックするか、「編集」でボックスにそれを取り込みます。提案が単独で送信されることはありません。',
  'Son mesaj kişiden geldiyse öneri kendiliğinden hazırlansın (kapalıysa ✨ düğmesiyle istenir)' => '相手から最後のメッセージが届いたときに自動的に提案を準備します (オフの場合は、✨ ボタンで質問します)',
  'Kurum bilgisi ve üslup' => '組織の情報とトーン',
  'Ör. Derneğimiz İstanbul\'da fidan dikimi yapar. Dikimler her yıl Kasım–Mart arasında yapılır. Sertifika bağıştan sonra WhatsApp\'tan gönderilir. Samimi ama resmi bir dil kullan.' => '例:私たちの協会はイスタンブールで苗木を植えています。植え付けは毎年11月から3月の間に行われます。証明書は寄付後にWhatsAppで送信されます。温かみのある、しかしフォーマルな口調を使用します。',
  'Öneri ve asistan bu bilgileri kullanır. Bağış türleri, fiyatlar, banka bilgisi ve hazır cevaplar ayrıca otomatik eklenir.' => '提案とアシスタントはこれを使用します。寄付の種類、価格、銀行詳細、クイック返信が自動的に追加されます。',
  'Öneri sağlayıcısı' => '提案プロバイダー',
  'Bağış asistanı (otomatik cevap)' => '寄付アシスタント(自動返信)',
  'Açıkken asistan gelen mesajlara kendisi cevap verir: karşılar, hitap için adını sorar, bağış seçeneklerini ve fiyatları gönderir, isteğe bağlı e-posta ve "kimin adına" bilgilerini alır, her değişiklikte özet gösterip onay ister. Onaydan sonra Flux Donate\'ta "ödeme bekleniyor" kaydı açar ve bağış linki ile alıcı adı, IBAN, açıklamayı ayrı mesajlar hâlinde gönderir. Konu bağış dışına çıkarsa sohbeti ekibe devreder.' => 'オンの場合、アシスタントは自ら応答します。挨拶し、宛先を尋ねる名前を尋ね、寄付のオプションと価格を送信し、オプションで電子メールと「誰の名前で」を収集し、変更のたびに確認を求めます。確認後、Flux Donate で「支払い待ち」レコードが開き、寄付リンク、受取人、IBAN、参照先が別のメッセージとして送信されます。トピックが寄付を残すと、チャットがチームに渡されます。',
  'Flux Donate eklentisi etkin değil; asistan bağış kaydı açamaz.' => 'Flux Donate プラグインはアクティブではありません。アシスタントは寄付記録を作成できません。',
  'Talimat, belgeler, AI sohbetleri ve test sohbeti' => '説明書、ドキュメント、AI チャット、テスト チャット',
  'Bağış asistanını aç (tümünü kapatmak için işareti kaldırın)' => '寄付アシスタントをオンにします (どこでもオフにするにはチェックを外します)',
  'Hangi sohbetlerde cevap versin' => 'どのチャットに返信すべきか',
  'Tüm sohbetlerde (önerilen)' => 'すべてのチャットで (推奨)',
  'Temsilciye atanmamış sohbetlerde' => 'エージェントに割り当てられていないチャット内',
  'Yalnız mesai saatleri dışında' => '勤務時間外のみ',
  'Bir temsilci sohbete yazdığında (panelden ya da telefondan) asistan o sohbette aşağıdaki süre kadar susar. Sohbet başlığındaki asistan düğmesiyle sohbet bazında açılıp kapatılır.' => 'エージェントが (パネルまたは電話から) チャットに書き込みを行うと、アシスタントは以下の時間の間、そこで沈黙を保ちます。チャット ヘッダーのアシスタント ボタンを使用して、チャットごとにオンまたはオフにします。',
  'Test modu: yalnız aşağıdaki numaralarda cevap ver' => 'テストモード: 以下の番号にのみ返信してください',
  'Test numaraları' => '検査番号',
  'Virgül ya da satır ile ayırın. Test modu kapalıyken kullanılmaz.' => 'カンマまたは改行で区切ります。テストモードがオフの場合は使用されません。',
  'Temsilci yazınca susma (saat)' => 'エージェントが書き込みを行った後は静かになります (時間)',
  'Fiyat listesindeki adetler' => '価格表の数量',
  'Konuşma geçmişi (saat)' => '会話履歴(時間)',
  'Asistan cevaptan önce bu süredeki tüm mesajları okur.' => '応答する前に、アシスタントはこの期間のすべてのメッセージを読みます。',
  'Asistanın sunduğu bağış türleri' => 'アシスタントが提供する寄付の種類',
  'Hiçbiri seçilmezse açık olan tüm türler sunulur. Yeni tür Flux Donate\'ta açıldığında asistan onu da bilir.' => '何も選択されていない場合は、すべてのオープン タイプが提供されます。新しいタイプが Flux Donate で開かれると、アシスタントもそれを認識します。',
  'Dekont ön kontrolü: kişi dekont gönderince yapay zekâ tutarı, alıcıyı ve IBAN\'ı bağışla karşılaştırır, sonucu kişiye söyler, dosyayı bağış kaydına ekler ve son onay için sohbeti ekibe devreder (ödendi işaretlemez)' => '領収書の事前チェック: 連絡先が領収書を送信すると、AI が金額、受取人、および IBAN を寄付と比較し、結果を連絡先に伝え、ファイルを寄付記録に添付して、最終承認のためにチャットをチームに渡します (支払い済みとはマークされません)。',
  'Fiyat listesinin son satırı' => '価格表の最後の行',
  'Ödeme bilgileri' => 'お支払い詳細',
  'Alıcı adı ve IBAN boşsa WooCommerce › Ödemeler › Havale / EFT ayarındakiler kullanılır (siparişlerde görünen hesap). Yalnız asistan için farklı hesap istiyorsanız doldurun.' => '受信者と IBAN が空の場合、WooCommerce › 支払い › 銀行振込のものが使用されます (注文に表示されているアカウント)。アシスタントが別のアカウントを使用する必要がある場合にのみ入力してください。',
  'Alıcı adı' => '受信者名',
  'Havale açıklaması' => '転送の説明',
  'Değişkenler: {type}, {name}, {amount}, {quantity}' => '変数:{type}、{name}、{amount}、{quantity}',
  'Bağış sayfası adresi' => '寄付ページURL',
  'Linke seçilen tür ve adet eklenir (?flxb_opt=…&flxb_qty=…).' => '選択したタイプと数量がリンクに追加されます (?flxb_opt=...&flxb_qty=...)。',
  'Ödeme bilgilerinden sonraki mesaj' => '支払い詳細後のメッセージ',
  'Bağış iptali onay sorusu' => '寄付キャンセルに関する質問',
  'Asistan yalnız ödenmemiş bağışları, kişinin onayıyla iptal eder. Boşsa varsayılan metin. Değişkenler: {bagis}, {tutar}.' => 'アシスタントは、本人の確認を得て、未払いの寄付のみをキャンセルします。空 = デフォルトのテキスト。変数:{bagis}、{tutar}。',
  'Günlük sınır dolunca gönderilen mesaj' => '1 日の制限に達したときに送信されるメッセージ',
  'Sohbet o günkü cevap sınırına ulaşınca bir kez gider, sohbet ekibe devredilir. Sınır sohbetin ⋮ menüsü › Asistan kullanımı ekranından sıfırlanır.' => 'チャットがその日の返信制限に達したときに 1 回送信されます。チャットはチームに渡されます。チャットの ⋮ メニュー › アシスタントの使用状況からリセットします。',
  'Ekibe devrederken gönderilen mesaj' => 'チームへの引き継ぎ時に送信されるメッセージ',
  'Asistan cevap veremezse giden mesaj' => 'アシスタントが応答できないときに送信されるメッセージ',
  'Yapay zekâ hata verir, süre aşılır ya da yoğunlukta sıra çok uzarsa kişiye bu mesaj gider ve sohbet ekibe devredilir; kişi hiçbir durumda cevapsız kalmaz.' => 'AI が失敗した場合、制限時間に達した場合、またはキューが長すぎる場合、このメッセージが送信され、チャットはチームに渡されます。その人が答えを持たずに放置されることは決してありません。',
  'Bekleme mesajından önce en az (sn)' => 'メッセージを保持するまでの最小待機時間 (複数可)',
  'Kişinin mesajından bu kadar saniye geçmeden bekleme mesajı gitmez; bu arada asistan yeniden dener.' => '保留中のメッセージは、その人のメッセージからこの秒数が経過するまで送信されません。その間、アシスタントは再試行します。',
  'Bir cevabın en uzun süresi (sn)' => '1 つの回答にかかる最長時間 (秒)',
  'Hostinger istekleri ~60 sn\'de kesebilir; 50 önerilir.' => 'Hostinger はリクエストを最大 60 秒でカットできます。 50が推奨されます。',
  'Devirde bildirim gidecek numaralar' => 'ハンドオフ時に通知される番号',
  'Asistan bir sohbeti ekibe devredince bu numaralara aynı hattan WhatsApp mesajı gider: kişinin adı, telefonu, nedeni, son mesajları ve panel linki. Virgül ya da satır ile ayırın. Bu numaralarla asistan konuşmaz.' => 'アシスタントがチャットをチームに引き渡すと、連絡先の名前、電話番号、理由、最後のメッセージ、パネル リンクといった WhatsApp メッセージが同じ回線からこれらの番号に送信されます。カンマまたは改行で区切ります。アシスタントはこれらの番号とは会話しません。',
  'Kişi bunlardan birini yazınca asistan beklemeden yukarıdaki devir mesajını gönderir ve o sohbette kapanır. Boş bırakılırsa örnekteki liste kullanılır.' => '連絡先がこれらのいずれかを書き込むと、アシスタントはすぐに上記のハンドオフ メッセージを送信し、そのチャットをオフにします。空のままにすると、サンプルのリストが使用されます。',
  'Asistana ek talimatlar' => 'アシスタントへの追加指示',
  'Ör. Fidanların dikileceği yer: Kocaeli. Sertifikalar bağış onaylanınca gönderilir.' => '例:コジャエリには苗木が植えられています。寄附確認後に証明書を発送いたします。',
  'Kişi mesaj istemeyince gönderilen son mesaj' => '連絡先がオプトアウトしたときの最後のメッセージ',
  'Kişi "bana mesaj atmayın" gibi bir şey yazınca asistan bu mesajı gönderir ve kişiyi kara listeye alır. Kara listedeki kişiye WhatsApp, e-posta ve SMS gitmez; listeyi Sohbetler › ☰ › Kara liste\'den yönetirsiniz.' => '誰かが「メッセージを送らないでください」のような内容を書き込んだ場合、アシスタントはこのメッセージを送信し、ブロックリストに登録します。ブロックリストに登録された人は、WhatsApp、電子メール、SMS を受け取りません。チャット › ☰ › ブロックリストでリストを管理します。',
  'Kişi hafızası ve arka plan işleri' => 'コンタクトメモリとバックグラウンドジョブ',
  'Kişi hafızası: asistan kişinin kalıcı bilgilerini (hitap, yakınlarının adı, numaralar, tercihler) hatırlar; süresi dolan sohbetler özetlenir' => '連絡先の記憶: アシスタントは永続的な詳細 (住所の形式、親戚の名前、番号、好み) を記憶します。期限切れのチャットがまとめられています',
  'Sohbet kaç saat sessiz kalınca özetlensin' => '(時間) 沈黙が続いた後にチャットを要約する',
  'Aynı anda en fazla iş' => '同時に最大ジョブ数',
  'Aynı anda cevap yazılabilecek kişi sayısı. Asistan cevapları her zaman önce gelir; cevap yazılan ya da sırada bekleyen kişi varken özet başlamaz. Her iş bir PHP işçisi kullanır: paylaşımlı hostingde sitelerin toplam işçi sınırının yarısını geçmeyin (ör. 60 işçide 20-30).' => '同時に何人まで回答できるか。アシスタントの応答は常に最初に行われます。誰かが応答しているか待っている間は、要約は開始されません。各ジョブは 1 つの PHP ワーカーを使用します。共有ホスティングでは、サイトの総ワーカー制限の半分未満に抑えてください (例: 60 ワーカーのうち 20 ~ 30 人)。',
  'Yalnız cevaplara ayrılan işçi' => '返信用に予約されたワーカー',
  'Bu kadar işçi hiçbir zaman özet ya da hatırlatıcı almaz.' => 'これほど多くの従業員は、概要やリマインダーをまったく受け取らないのです。',
  'Özet saatleri' => '概要時間',
  'Özetler yalnız bu saatler arasında yapılır (elle "Şimdi özetle" hariç). İkisi aynıysa her saat.' => '要約は、これらの時間の間にのみ実行されます (手動の「今すぐ要約」を除く)。両方が同じであればいつでも。',
  'Kişi sesli mesaj gönderirse asistan sesi metne çevirip cevap versin (metin panelde sistem satırı olarak da görünür)' => '誰かが音声メッセージを送信すると、アシスタントがそれをテキストに変換して返信します (テキストはシステム行としてもパネルに表示されます)。',
  'En uzun ses (sn)' => '最長の音声メッセージ (秒)',
  'Daha uzun seslerde asistan "ses çok uzun olduğu için dinleyemedik" der.' => '長いメッセージの場合、アシスタントは「音声メッセージが長すぎて聞くことができませんでした」と言います。',
  'Sesli mesaj modeli (isteğe bağlı)' => '音声メッセージモデル(オプション)',
  'Ses okuyan ucuz model (Gemini Flash Lite)' => '廉価オーディオモデル(Gemini Flash Lite)',
  'Ses okuyan bir OpenRouter modeli olmalı (Claude ses okumaz). OpenRouter anahtarı gerekir.' => 'オーディオを受け入れる OpenRouter モデルである必要があります (Claude は受け入れません)。 OpenRouter キーが必要です。',
  'Görseller' => '画像',
  'Gerekince asistan görsel (tablo, rapor, şema) çizsin; WhatsApp\'a resim olarak gider, metin ayrıca gider' => '必要に応じてアシスタントに画像 (表、レポート、図) を描画させます。 WhatsApp に画像として送信され、テキストは個別に送信されます',
  'Flux AI görsel çeviricisi kullanılır (Flux AI & MCP › Ayarlar › Görseller).' => 'Flux AI イメージ レンダラーが使用されます (Flux AI と MCP › 設定 › 画像)。',
  'Sunucuda görsel çevirici yok: Flux AI & MCP › Ayarlar › Görseller\'e Gotenberg adresi girin ya da Imagick (SVG) kurulsun. O zamana kadar asistan görsel çizmez.' => 'サーバー上に画像レンダラーがありません: Flux AI & MCP › 設定 › 画像 に Gotenberg アドレスを入力するか、Imagick (SVG) をインストールします。それまでアシスタントは画像を描画しません。',
  'Flux AI 0.2.0 ya da sonrası kurulunca çalışır.' => 'Flux AI 0.2.0 以降がインストールされていると動作します。',
  'Başkası adına bağış' => '誰かに代わって寄付する',
  'Bağış başkası adınaysa ve o kişinin numarası verildiyse (kişi kartı ya da yazılı numara), ödeme onaylanınca sertifika o numaraya da WhatsApp\'tan gitsin' => '寄付が他人の名前であり、その番号が指定されている場合(連絡先カードまたは入力された番号)、支払いが承認されたら、WhatsApp のその番号にも証明書を送信してください。',
  'Sertifikadan önce giden mesaj' => '証明書の前にメッセージが送信される',
  'Ardından Flux Certificates\'daki WhatsApp sertifika mesajı gider. Değişkenler: {ad}, {bagisci}, {bagis}, {brand}.' => '次に、Flux Certificates から WhatsApp 証明書メッセージが送信されます。変数:{ad}、{bagisci}、{bagis}、{brand}。',
  'Kişi isterse asistan hatırlatıcı kurar (ör. "her ay fidan dikimini hatırlat", "her ay son projelerinizi gönderin", "her ay benden bir fidan iste"); zamanı gelince asistan mesajı yazıp gönderir' => '誰かが尋ねると、アシスタントはリマインダーを設定します(例:「毎月苗木を植えることを思い出させて」、「毎月最新のプロジェクトを送って」、「毎月苗木をくれと頼んで」)。期限が来ると、アシスタントがメッセージを書いて送信します',
  'Saat söylenmezse' => '時間が与えられないとき',
  'Kişi başına en fazla' => '最大でもお一人様あたり',
  'Personel (Flux Roles)' => 'スタッフ (フラックスの役割)',
  'Flux Roles 1.1.0 kurulunca çalışır: numarası Profil › WhatsApp numarası alanına yazılmış kullanıcılar asistanda yetkilerine göre ek araçlar kullanır.' => 'Flux ロール 1.1.0 がインストールされると機能します。番号が [プロファイル] › WhatsApp 番号に設定されているユーザーは、権限に基づいて追加のアシスタント ツールを取得します。',
  'Personel numarasından yazana asistan yetkisine göre ek araçlar açsın (başkası adına bağış ve ödeme linki, bağışçılarım, genel rapor)' => '許可を得てスタッフ番号に追加のアシスタント ツールを提供します (支払いリンクを持つ誰かに代わって寄付、私の寄付者、一般的なレポート)',
  'Referansı olduğu bağış ödenince ya da iptal olunca personele WhatsApp bildirimi gitsin' => '紹介した寄付が支払われたとき、またはキャンセルされたときにスタッフに WhatsApp で通知する',
  'Personel adına açılan bağışta bağışçıya ilk mesaj' => 'スタッフが開く寄付者への最初のメッセージ',
  'Merhaba {ad} 🌱 {personel} aracılığıyla {bagis} bağış talebiniz alındı. Ödemeyi aşağıdaki bilgilerle yapabilirsiniz.' => 'こんにちは{ad}🌱{personel}経由で{bagis}の寄付リクエストを受け取りました。以下の詳細でお支払いいただけます。',
  'Ardından ödeme linki ve havale bilgileri gider. Değişkenler: {ad}, {adsoyad}, {personel}, {bagis}.' => '支払いリンクと銀行の詳細が続きます。変数:{ad}、{adsoyad}、{personel}、{bagis}。',
  'Personelin referansı olduğu bağış ödenip sertifika oluşunca sertifika personele de WhatsApp\'tan gitsin (bağışçıya gittiği gibi)' => 'スタッフメンバーから紹介された寄付金が支払われ、証明書が作成されたら、それを WhatsApp でスタッフメンバーにも送信します (寄付者と同じように)',
  'Personele sertifikadan önce giden mesaj' => '証明書を受け取る前にスタッフに送信されたメッセージ',
  'Değişkenler: {ad}, {bagisci}, {bagis}, {no}, {brand}.' => '変数:{ad}、{bagisci}、{bagis}、{no}、{brand}。',
  'Personel bir bağışın sertifikasını en fazla kaç kez yeniden gönderebilir' => 'スタッフが寄付証明書を何回再送できるか',
  'Asistan göndermeden önce kime gideceğini yazıp onay ister. 0: kapalı.' => 'アシスタントは受信者をリストし、送信する前に確認を求めます。 0: オフ。',
  'Kayıt sorgusunda kod doğrulama' => 'レコード検索のコード検証',
  'Kişi kayıtlarını sorar ve numarası gizliyse (ya da başka numara/e-postayla bağış yaptıysa) verdiği numaraya ya da e-postaya kod gönder; kod doğrulanınca onun kayıtları da gösterilir' => '誰かが自分の記録を要求し、その番号が隠されている場合(または別の番号/電子メールで寄付した場合)、その人が提供した番号または電子メールにコードを送信します。確認されると、その記録も表示されます',
  'Kod geçerliliği (dk)' => 'コードの有効性 (分)',
  'En fazla başarısız deneme' => '失敗した試行の最大数',
  'Gönderilemeyen, yanlış ya da süresi dolan kodlar sayılır. Sınırda kişiye aşağıdaki mesaj gider, ekibe haber verilir; asistan diğer sorulara cevap verir ama 24 saat kayıt bilgisi vermez.' => '送信できなかったコード、間違ったコード、期限切れのコードもカウントされます。制限に達すると、その人は以下のメッセージを受け取り、チームに通知されます。アシスタントは他の質問に答え続けますが、記録の詳細は 24 時間共有されません。',
  'Telefona kod' => '電話へのコード',
  'WhatsApp, gitmezse SMS' => 'WhatsApp、失敗した場合はSMS',
  'Yalnız WhatsApp' => 'WhatsAppのみ',
  'Yalnız SMS' => 'SMSのみ',
  'SMS, Flux Mail\'te SMS bağlantısı (ör. Netgsm) varsa kullanılır.' => 'Flux Mail に SMS 接続 (Netgsm など) がある場合、SMS が使用されます。',
  'Doğrulama yapılamazsa giden mesaj' => '検証失敗時のメッセージ',
  'WhatsApp/SMS kod mesajı' => 'WhatsApp/SMS コードメッセージ',
  'Boşsa varsayılan metin. Değişkenler: {kod}, {dk}, {marka}. E-posta metni Flux Mail › E-posta şablonları\'ndan değişir.' => '空の場合のデフォルトのテキスト。変数:{kod}、{dk}、{marka}。電子メールのテキストは、Flux Mail › 電子メール テンプレートで編集します。',
  'Sitedeki içerikler' => 'サイトのコンテンツ',
  'Asistan sitede yayında olan içeriklerde arama yapabilsin (ör. "fidan dikimi geçen bir gönderiniz var mı")' => 'アシスタントが公開されているサイトのコンテンツを検索できるようにします (例: 「植樹に関する投稿はありますか」)',
  'Aranacak içerik türleri' => '検索するコンテンツの種類',
  'Yalnız yayında ve şifresiz içerikler döner. Taslak, özel ve şifreli içerik hiçbir zaman gösterilmez.' => 'パスワードなしで公開されたコンテンツのみが返されます。下書き、プライベート、パスワードで保護されたコンテンツは表示されません。',
  'Hiç paylaşılmayacak kategori ve etiketler' => '決して共有しないカテゴリとタグ',
  'ör. kurumsal-teklifler, ic-duyuru' => '例:企業オファー、社内通知',
  'Ad ya da kısa ad, virgülle. Tek bir içeriği gizlemek için düzenleme ekranındaki "Asistan bu içeriği kişilerle paylaşmasın" kutusunu işaretleyin.' => '名前またはスラッグ、カンマ区切り。単一のアイテムを非表示にするには、その編集画面で「アシスタントにこのコンテンツを共有させない」にチェックを入れます。',
  'Ekip grubu' => 'チームグループ',
  'WhatsApp grubu' => 'WhatsAppグループ',
  '— Seçilmedi —' => '— 未選択 —',
  'Hattın üye olduğu gruplar. Yeni açtığınız grup görünmüyorsa' => 'ラインがメンバーとなっているグループ。作成したばかりのグループが見つからない場合は、',
  'listeyi yenileyin' => 'リストを更新する',
  'Kişilerden gelen mesajları ve verilen cevapları (asistan, ekip, otomatik) bu gruba yaz' => '受信メッセージと返信 (アシスタント、チーム、自動) をこのグループに投稿します',
  'Devir bildirimini numaralara ayrı ayrı değil bu gruba gönder; yukarıdaki numaralar mesajda etiketlenir' => '各番号の代わりにこのグループにハンドオフ通知を送信します。上記の数字はメッセージに記載されています',
  'Gruba son gönderim başarısız: ' => 'グループへの最後の投稿は失敗しました:',
  'Fiyat listesi önizlemesi' => '価格表のプレビュー',
  'Asistanın çalışması için önce yapay zekâ anahtarı ve model girin.' => 'アシスタントが機能できるように、最初に AI キーとモデルを入力します。',
  'Asistan şu an konuşmaz: ' => 'アシスタントは現在応答しません:',
  'WhatsApp asistanı' => 'WhatsAppアシスタント',
  'Asistan bu içeriği kişilerle paylaşmasın' => 'アシスタントにこのコンテンツを共有させないでください',
  'Personel %1$s düzeltti; yerine #%2$d açıldı.' => 'スタッフメンバー%1$sによって修正されました。 #%2$dが代わりにオープンされました。',
  'Bağış #%1$d iptal edildi, yerine #%2$d açıldı.' => '寄付 #%1$dはキャンセルされ、代わりに #%2$dがオープンされました。',
  'Personel %s WhatsApp asistanıyla oluşturdu.' => 'WhatsApp アシスタントを介してスタッフ メンバー%sによって作成されました。',
  'Personel %1$s aracılığıyla bağış kaydı açıldı: %2$s (#%3$d)' => 'スタッフメンバー%1$s:%2$s(#%3$d) を通じて寄付が開始されました',
  'Sertifikanız 🌱' => 'あなたの証明書 🌱',
  'Personel %1$s sertifikayı WhatsApp\'tan yeniden gönderdi: %2$s' => 'スタッフ メンバー%1$sが WhatsApp で証明書を再送信しました:%2$s',
  '✅ Bağışçınız ödedi: *%1$s* · %2$s #%3$d' => '✅ あなたの寄付者が支払ったもの: *%1$s* ·%2$s#%3$d',
  '❌ Bağış iptal edildi: *%1$s* · %2$s #%3$d' => '❌ 寄付がキャンセルされました: *%1$s* ·%2$s#%3$d',
  'Çıkartma' => 'ステッカー',
  'Anket' => '投票',
  'Desteklenmeyen mesaj' => 'サポートされていないメッセージ',
  '{a} satır eklendi, {d} satır çıkarıldı' => '{a}行が追加され、{d}行が削除されました',
  'Yapay zekâ anahtarı ya da modeli girilmemiş.' => 'AI キーまたはモデルが入力されていません。',
  'Asistan kapalı; gelen mesajlara cevap vermiyor.' => 'アシスタントはオフになっており、受信メッセージに応答しません。',
  'Test modu açık: asistan yalnız test numaralarına cevap veriyor.' => 'テスト モードがオンです。アシスタントはテスト番号にのみ応答します。',
  'Asistanın çalışma özeti' => 'アシスタント活動の概要',
  'Detayı gizle' => '詳細を隠す',
  'Detay' => '詳細',
  'Harcama (USD)' => '支出 (USD)',
  'Cevaplanan soru' => '回答された質問',
  'Cevap verilen kişi' => '人々は答えました',
  'Bağışa yönlendirilen kişi' => '寄付をするように指示された人々',
  'Açılan bağış kaydı' => '寄付記録が作成されました',
  'Onaylanan bağış · {a}' => '確認された寄付 ·{a}',
  'Okunan dekont · ✓{a} ✕{b}' => '領収書の読み取り · ✓{a}✕{b}',
  'Ekibe devir' => 'チームへの引き継ぎ',
  'Hafıza token · {p} kişi' => 'メモリトークン・{p}コンタクト',
  'Mesaj istemedi (kara liste)' => 'オプトアウト済み (ブロックリスト)',
  'Gönderilen hatırlatıcı' => '送信されたリマインダー',
  'Gönderilen kod · e-posta {e} · WhatsApp {w} · SMS {s}' => '送信されたコード · 電子メール{e}· WhatsApp{w}· SMS{s}',
  'Doğrulanan · telefon {p} · e-posta {e}' => '確認済み · 電話{p}· 電子メール{e}',
  'Kod sorunu · yanlış {w} · süresi doldu {x} · gitmedi {f}' => 'コードの問題 · 間違った{w}· 期限切れの{x}·{f}が配信されていない',
  'Doğrulanamadı, ekibe bildirildi' => '未確認、チームに通知済み',
