  'Grup' => 'グループ',
  'Mesajlar (sırayla)' => 'メッセージ(順番に)',
  '{tur}, {birim} ve {brand} kullanılabilir. Yalnız müşteri mesajı varsa asistan her birine sırayla cevap verir. Asistan mesajı eklerseniz devam senaryosu olur: yazılan geçmiş hazır verilir, asistan yalnız en sondaki müşteri mesajına cevap verir.' => '{tur}、{birim}および{brand}を使用できます。顧客メッセージのみがある場合、アシスタントはそれぞれのメッセージに順番に返信します。アシスタント メッセージを追加すると、継続シナリオになります。書き込まれた履歴はそのまま提供され、アシスタントは最後の顧客メッセージにのみ返信します。',
  'Ör. payment_info, cancel_donation, receipt_check. Bu sitede kapalı araç bakılmaz.' => '例:支払い情報、寄付キャンセル、領収書チェック。このサイトで無効になっているツールはチェックされていません。',
  'Kim yazıyor?' => '誰が書いていますか?',
  'Başlangıç durumu (test)' => '開始状態(テスト)',
  'Senaryo test sohbetindeki gibi izole oynar; burada seçilenler yalnız bu testte vardır. Müşteri mesajında {kod} test panelindeki doğrulama kodu olur.' => 'シナリオはテスト チャットのように分離して実行されます。ここで選択したものは、このテスト内にのみ存在します。顧客メッセージでは、{kod}がテスト パネルからの確認コードになります。',
  'Sonda durum' => '終了状態',
  'Konuşma bitince test durumuna bakılır (bağış açıldı mı, iptal edildi mi, kod gitti mi…). Bu sitede kapalı araç bakılmaz.' => '会話が終了すると、テスト状態がチェックされます (寄付が開かれたか、キャンセルされたか、コードが送信されたかなど)。このサイトで無効になっているツールはチェックされていません。',
  'Değerlendirici ölçütü' => '審査基準',
  'Boşsa değerlendirici çağrılmaz. Kurala dökülemeyen kalite beklentileri buraya.' => '空の場合、ジャッジは呼ばれません。ルールとして記述できない品質への期待をここに記述します。',
