  'Veritabanı tabloları' => 'データベーステーブル',
  'Eksik tablo: %s. Eklentiyi devre dışı bırakıp yeniden etkinleştirin.' => 'テーブルがありません:%s。プラグインを非アクティブ化し、再度アクティブ化します。',
  'Tablolar hazır (şema %s).' => 'テーブルの準備ができました (スキーマ%s)。',
  'Şema güncellemesi bekliyor; yönetim panelinde bir sayfa açınca tamamlanır.' => 'スキーマの更新は保留中です。管理パネルでページを開くと完了します。',
  'Medya klasörü' => 'メディアフォルダー',
  'uploads/flx-chat klasörüne yazılamıyor; gelen fotoğraf, ses ve belgeler kaydedilemez. Klasör izinlerini kontrol edin.' => 'Uploads/flx-chat に書き込めません。受信した写真、音声メモ、ドキュメントは保存できません。フォルダーの権限を確認してください。',
  'Klasör koruması (.htaccess) yok; ilk medya kaydında oluşturulur.' => 'フォルダー保護 (.htaccess) がありません。最初に保存されたメディアを使用して作成されます。',
  'Yazılabilir ve dışarıya kapalı.' => '書き込み可能で非公開です。',
  'Var.' => '利用可能です。',
  'Yok; asistan cevap hazırlarken "yazıyor…" göstergesi yalnız kısa süre görünür.' => '行方不明。アシスタントが応答を準備している間、「入力中...」インジケーターは短時間だけ表示されます。',
  'Temsilci rolündeki kullanıcı sayısı: %d.' => 'エージェントの役割を持つユーザー:%d。',
