  'Panelin canlı güncellemesi' => 'ライブパネルの更新',
  'Son güncelleme isteği %1$s. Panel açıkken %2$d sn\'de bir yeni mesaj sorulur (arka plandaki sekmede 60 sn).' => '最終更新リクエスト%1$s。パネルが開いている間、%2$d秒 (バックグラウンド タブでは 60 秒) ごとに新しいメッセージがチェックされます。',
  'Sohbet ekranı henüz hiç açılmadı.' => 'まだチャット画面は開いていません。',
  'WhatsApp hattı' => 'WhatsAppライン',
  'Hiç hat eklenmemiş.' => '行は追加されていません。',
  '%s: bağlantı bilgisi' => '%s: 接続の詳細',
  'Flux Mail bağlantısı kullanılıyor: %s.' => 'Flux Mail 接続の使用:%s。',
  'Hâlâ Flux Certificates\'daki eski sağlayıcı kullanılıyor; bağlantıyı Flux Mail\'e taşıyıp burada seçin.' => 'Flux 証明書では依然として古いプロバイダーを使用しています。接続を Flux Mail に移動し、ここで選択します。',
  'Flux Certificates\'daki Evolution sağlayıcısı kullanılıyor.' => 'Flux 証明書の Evolution プロバイダーを使用します。',
  'API adresi, key ve instance bu eklentide girilmiş.' => 'このプラグインにはAPIのURL、キー、インスタンスを入力します。',
  '%s: hat durumu' => '%s: 回線ステータス',
  'Telefon bağlı (son bilgi %s).' => '電話が接続されました (最後に表示されたのは%s)。',
  'Henüz denenmedi. "Bağlantıyı test et" düğmesine basın.' => 'まだテストされていません。 「接続テスト」を押します。',
  'Telefon bağlı değil (durum: %1$s, %2$s). "QR ile bağla" ile yeniden bağlayın.' => '電話が接続されていません (状態:%1$s、%2$s)。 「QRで接続」で再接続してください。',
  '%s: Evolution API sürümü' => '%s: Evolution API バージョン',
  'Evolution API %s kullanılıyor. Gizli numaralı (@lid) kişilere cevap gitmeyebilir; sunucuyu 2.3 veya üstüne güncelleyin.' => 'Evolution API%sが使用されています。非表示の番号 (@lid) 連絡先への返信は失敗する場合があります。サーバーを 2.3 以降に更新します。',
  '%s: webhook (gelen mesajlar)' => '%s: Webhook (受信メッセージ)',
  'Evolution\'dan hiç olay gelmedi; gelen mesajlar panele düşmez. "Webhook\'u kur" düğmesine basın.' => 'Evolution からイベントが到着していません。受信メッセージはパネルに表示されません。 「Webhookを設定する」を押します。',
  'Son olay %s geldi. Hat sessiz olabilir; emin olmak için kendinize mesaj atın ya da webhook\'u yeniden kurun.' => '最後のイベント%sが到着しました。回線が静かなだけかもしれません。自分にメッセージを送信するか、Webhook を再度設定して確認してください。',
  'Son olay %s geldi.' => '最後のイベントが%sに到着しました。',
  'Flux Mail entegrasyonu' => 'Flux メールの統合',
  'Etkin: WhatsApp bağlantıları İletişim › Bağlantılar\'dan alınır.' => 'アクティブ: WhatsApp 接続は、通信 › 接続から取得されます。',
  'Flux Mail etkin değil; bağlantılar Flux Certificates\'dan ya da bu eklentiden alınır.' => 'Flux Mail はアクティブではありません。接続は Flux 証明書またはこのプラグインから取得されます。',
  'Flux Certificates entegrasyonu' => 'Flux 証明書の統合',
  'Etkin: sohbetten sertifika oluşturulup gönderilebilir.' => 'アクティブ: チャットから証明書を作成および送信できます。',
  'Flux Certificates etkin değil; sohbetten sertifika işlemleri kapalı.' => 'Flux 証明書はアクティブではありません。チャットでの証明書アクションがオフになっています。',
  'Flux Donate entegrasyonu' => 'Flux Donateの統合',
  'Etkin: sohbetten bağış kaydı, dekont eşleştirme ve asistan kullanılabilir.' => 'アクティブ: 寄付記録、領収書の照合、アシスタントはチャットから利用できます。',
  'Flux Donate etkin değil; bağış kaydı, dekont eşleştirme ve bağış asistanı kapalı.' => 'Flux Donate はアクティブではありません。寄付記録、領収書の照合、寄付アシスタントがオフになっています。',
  'Flux AI & MCP eklentisi kurulu değil; yapay zekâ özellikleri (öneri, asistan, dekont okuma, sesli mesaj, özet) kapalı. Flux AI\'yi kurup anahtarı oraya girin.' => 'Flux AI および MCP プラグインはインストールされていません。 AI 機能 (提案、アシスタント、レシート読み上げ、音声メッセージ、要約) はオフになっています。 Flux AI をインストールし、そこにキーを入力します。',
  'Flux AI\'de anahtar girilmemiş; mesaj önerisi ve asistan kapalı.' => 'Flux AI にキーが入力されていません。メッセージの提案とアシスタントはオフになっています。',
  'Anahtar var ama model seçilmemiş.' => 'キーは保存されましたが、モデルが選択されていません。',
  'Seçili model (%s) için Flux AI\'de sağlayıcının anahtarı girilmemiş.' => '選択したモデル (%s) の Flux AI にプロバイダー キーが入力されていません。',
  'Anahtar kayıtlı, model: %s. Canlı deneme için "Bağlantıyı test et".' => 'キーが保存されました、モデル:%s。ライブチェックには「接続テスト」を使用します。',
  'Bağış asistanı' => '寄付アシスタント',
  'Kapalı.' => 'オフ。',
  'Yapay zekâ anahtarı veya modeli eksik.' => 'AI キーまたはモデルがありません。',
  'Açık ama konuşmuyor: ' => 'オンだが応答がない:',
  'Açık. Sunulan bağış türleri: %s.' => 'オン。提供される寄付の種類:%s。',
  '%s araç (tools) desteklemiyor; asistan için araç destekli bir model seçin.' => '%sはツールをサポートしていません。アシスタントにはツール対応モデルを選択してください。',
  'Dekont okuma modeli' => 'レシート読み取りモデル',
  '%s görsel okuyamıyor; dekont ön kontrolü çalışmaz. Görsel destekli bir dekont okuma modeli seçin.' => '%sはイメージを読み取れません。領収書の事前チェックは機能しません。画像対応のレシート読み取りモデルを選択してください。',
  'Asistanın ödeme bilgileri' => 'アシスタントの支払い詳細',
  'Alıcı adı ve IBAN tanımlı.' => '受信者名とIBANが設定されています。',
  'Alıcı adı veya IBAN eksik; onaydan sonra havale bilgisi gönderilemez.' => '受信者名または IBAN がありません。確認後に銀行口座情報を送信することはできません。',
  'Bağış sayfası linki' => '寄付ページへのリンク',
  'Bağış sayfası bulunamadı; asistan link göndermez.' => '寄付ページが見つかりません。アシスタントはリンクを送信しません。',
  'Arka plan istekleri' => 'バックグラウンドリクエスト',
  'Site kendine arka plan isteği atamadı (%1$s: %2$s). Sıradaki cevaplar ve benchmark yavaş ilerleyebilir; güvenlik eklentisi ya da sunucu güvenlik duvarı /wp-json/flx-chat/ isteklerini engelliyor olabilir.' => 'サイトはバックグラウンドリクエストをそれ自体に送信できませんでした (%1$s:%2$s)。応答がキューに入れられ、ベンチマークの動きが遅くなる可能性があります。セキュリティ プラグインまたはサーバー ファイアウォールが /wp-json/flx-chat/ リクエストをブロックしている可能性があります。',
  'hata' => 'エラー',
  'uyarı' => '警告',
  'tamam' => 'わかりました',
  '{marka} doğrulama kodunuz: {kod}' => '{marka}確認コード:{kod}',
  'Kod {dk} dakika geçerlidir. Bu kodu WhatsApp\'ta bizimle olan sohbete yazın. Bu isteği siz yapmadıysanız dikkate almayın.' => 'コードは{dk}分間有効です。 WhatsApp チャットにそれを入力してください。要求していない場合は、このメッセージを無視してください。',
  'Bir sıkıntı oldu, ekibimiz en kısa sürede sizinle iletişime geçecek 🌱 Bu arada başka bir sorunuz olursa yazabilirsiniz.' => '何か問題が発生しました。私たちのチームができるだけ早くご連絡いたします 🌱 その他、何かございましたらお気軽にご質問ください。',
  'Doğrulama denemesi başarısız (%1$d/%2$d): %3$s' => '検証の試行が失敗しました (%1$d/%2$d):%3$s',
  'Kişi kayıtlarını görmek istedi, doğrulama yapılamadı; ekipten biri iletişime geçmeli' => 'その人は自分の記録を見たいと思っていましたが、確認することができませんでした。チームの誰かが連絡する必要があります',
  'e-posta gönderilemedi (Flux Mail › SMTP ayarlarını kontrol edin)' => '電子メールを送信できませんでした (Flux Mail › SMTP 設定を確認してください)',
  'Asistan %1$s için doğrulama kodu gönderdi (%2$s).' => 'アシスタントは%1$s(%2$s) の確認コードを送信しました。',
  'kodun süresi doldu' => 'コードの有効期限が切れました',
  'yanlış kod' => '間違ったコード',
  'Kişi %s için kodu doğruladı; kayıt sorgusuna eklendi.' => 'その人は%sのコードを検証しました。それはレコード検索に追加されます。',
  'Claude modelleri ses okuyamaz; Ayarlar › Yapay zekâ › Sesli mesaj modelinden ses okuyan bir OpenRouter modeli seçin.' => 'クロード モデルは音声を読み取ることができません。 [設定] › AI › 音声メッセージ モデルでオーディオ対応の OpenRouter モデルを選択します。',
  'Ses metne çevrilemedi.' => '音声を転写できませんでした。',
  'Ses dosyası okunamadı.' => '音声ファイルを読み取れませんでした。',
  'Sesli mesaj (%1$s) metne çevrildi: %2$s' => '音声メッセージ (%1$s) 文字起こし:%2$s',
  'Sesli mesaj (%1$s) dinlenemedi: %2$s' => '音声メッセージ (%1$s) を処理できませんでした:%2$s',
  'Resmi WhatsApp Cloud API hattında bu işlem yok.' => 'このアクションは、公式の WhatsApp Cloud API ラインでは利用できません。',
  'WhatsApp 24 saat kuralı: kişi son 24 saatte yazmadığı için Cloud API serbest mesaj göndermiyor; yalnız onaylı şablon gider. Kişi yazınca yeniden deneyin.' => 'WhatsApp の 24 時間ルール: 連絡先は過去 24 時間にメッセージを書いていないため、Cloud API は自由形式のメッセージを送信しません。承認されたテンプレートのみを送信できます。彼らが書いたら、もう一度試してください。',
  'Cloud API hattı için Flux Mail 1.10.0 veya üstü gerekli.' => 'Cloud API ラインには Flux Mail 1.10.0 以降が必要です。',
  'Cloud API bu adrese (gizli numara ya da grup) gönderemez.' => 'Cloud API は、このアドレス (非表示の番号またはグループ) に送信できません。',
  'Cloud API hesabına ulaşılamadı (İletişim › Bağlantılar).' => 'Cloud API アカウント (İletişim › 接続) にアクセスできませんでした。',
  'Cloud API hattında QR yok; hesap İletişim › Bağlantılar\'da kurulur.' => 'Cloud API ラインには QR コードがありません。アカウントは İletişim › 接続 で設定されます。',
  'Dosya hazırlanamadı.' => 'ファイルを準備できませんでした。',
  'Flux AI görsel desteği yok.' => 'Flux AI は画像をサポートしていません。',
  'Görsel çevrilemedi.' => '画像をレンダリングできませんでした。',
  'Asistanın görseli gönderilemedi: ' => 'アシスタントの画像を送信できませんでした:',
  'Merhaba {first_name}, bağış kaydınızı oluşturduk: {donation}, toplam {amount}.' . chr(10) . '' . chr(10) . '{bank}' . chr(10) . '' . chr(10) . 'Ödemeyi yaptıktan sonra dekontu buradan gönderebilirsiniz. Teşekkür ederiz.' => '{first_name}さん、こんにちは。寄付記録{donation}、合計{amount}が作成されました。{bank}お支払い後、こちらから領収書をお送りください。ありがとう。',
  'Merhaba {first_name}, bağışınız kaydedildi: {donation}, toplam {amount}.' . chr(10) . '' . chr(10) . 'Desteğiniz için teşekkür ederiz.' => 'こんにちは{first_name}さん、あなたの寄付が記録されました:{donation}、合計{amount}。' . chr(10) . '' . chr(10) . 'ご支援ありがとうございます。',
  'Bu senaryoyu oynatacak eklenti kapalı.' => 'このシナリオを実行するプラグインは非アクティブです。',
  'Bu kullanıcının personel araçları yetkisi yok.' => 'このユーザーはスタッフツールを使用できません。',
  '%1$s bu sohbeti personel olarak bağladı: %2$s' => '%1$sがこのチャットをスタッフ メンバー%2$sにリンクしました',
  '%s sohbetin personel bağlantısını kaldırdı' => '%sがこのチャットのスタッフ リンクを削除しました',
  'Sohbet personele bağlandı' => 'スタッフメンバーにリンクされたチャット',
  'Personel bağlantısı kaldırıldı' => 'スタッフリンクが削除されました',
  '— Personel değil —' => '— スタッフではありません —',
  'WhatsApp bu kişinin numarasını gizliyor, asistan personeli numaradan tanıyamaz. Bu kişi ekibinizdense buradan bağlayın; asistan personel araçlarını açar.' => 'WhatsApp はこの人の番号を非表示にするため、アシスタントは番号でスタッフを認識できません。この人があなたのチームに属している場合は、ここでリンクすると、アシスタントがスタッフ ツールを開きます。',
  'Asistan personeli Flux Roles profilindeki numaradan tanır. Numara eşleşmiyorsa buradan bağlayabilirsiniz; numarası bilinen sohbette numara önceliklidir.' => 'アシスタントは、Flux ロール プロファイル内の番号によってスタッフを認識します。番号が一致しない場合は、ここでリンクできます。既知の番号とのチャットでは、その番号が最初に来ます。',
  'Bu kanal şu an kullanılamıyor.' => 'このチャンネルは現在利用できません。',
  'Site sohbeti' => 'サイトチャット',
  'WhatsApp, site sohbeti ve diğer kanallardan gelen tüm mesajlar burada canlı görünür. Soldan bir sohbet seçin.' => 'WhatsApp、サイトチャット、その他のチャネルからのすべてのメッセージがここにライブで表示されます。左側にあるチャットを選択します。',
  'WhatsApp (Evolution API) çağrı merkezi: gelen ve giden mesajları canlı görün, yeni sohbet başlatın, hazır cevaplar, etiketler, atama, dahili notlar, otomatik yanıtlar; sohbetten bağış (Flux Donate) ve sertifika (Flux Certificates) kaydı, dekont eşleştirme. OpenRouter ile yapay zekâ cevap önerisi ve otomatik bağış asistanı.' => 'WhatsApp (Evolution API) コールセンター: ライブの送受信メッセージの表示、新しいチャットの開始、返信定型文、タグ、割り当て、社内メモ、自動返信。チャットからの寄付(Flux Donate)と証明書(Flux Certificates)の登録、レシート照合。 OpenRouter による人工知能の応答提案と自動寄付アシスタント。',
  'WhatsApp (Evolution API) call center: see live incoming and outgoing messages, start new chat, canned replies, tags, assignment, internal notes, auto-replies; Donation (Flux Donate) and certificate (Flux Certificates) registration from chat, receipt matching. Artificial intelligence response suggestion and automatic donation assistant with OpenRouter.' => 'WhatsApp (Evolution API) コールセンター: ライブの送受信メッセージの表示、新しいチャットの開始、返信定型文、タグ、割り当て、社内メモ、自動返信。チャットからの寄付(Flux Donate)と証明書(Flux Certificates)の登録、レシート照合。 OpenRouter による人工知能の応答提案と自動寄付アシスタント。',
  'Hide' => '隠す',
  'Show' => '表示',
  'Deleted for everyone' => '全員から削除済み',
  'Hidden in the panel' => 'パネルで非表示',
  'Delete for everyone' => '全員から削除',
  'Hide in the panel only' => 'パネルでのみ非表示',
  'WhatsApp doesn\'t allow deleting a received message for everyone; it stays on the contact\'s phone and is only hidden in the panel.' => 'WhatsAppでは受信したメッセージを全員から削除できません。メッセージは相手の端末に残り、パネルでのみ非表示になります。',
  'Delete for everyone is turned off in the settings; the message is only hidden in the panel and stays on the contact\'s phone.' => '「全員から削除」は設定でオフになっています。メッセージはパネルでのみ非表示になり、相手の端末に残ります。',
  'This channel doesn\'t support delete for everyone; the message is only hidden in the panel and stays on the contact\'s phone.' => 'このチャネルは「全員から削除」に対応していません。メッセージはパネルでのみ非表示になり、相手の端末に残ります。',
  'The time limit for delete for everyone has passed (WhatsApp allows about {h} hours after sending). The message stays on the contact\'s phone and is only hidden in the panel.' => '「全員から削除」の期限を過ぎました（WhatsAppでは送信後約{h}時間まで）。メッセージは相手の端末に残り、パネルでのみ非表示になります。',
  'Only the sender or an administrator can delete this message for everyone; you can hide it in the panel.' => 'このメッセージを全員から削除できるのは送信者または管理者のみです。パネルで非表示にできます。',
  'If deleted for everyone, the message also turns into "This message was deleted" on the contact\'s phone. Time left: about {n} hours.' => '全員から削除すると、相手の端末でも「このメッセージは削除されました」と表示されます。残り時間：約{n}時間。',
  'Deleted messages are kept on the server: the chat shows a "This message was deleted" line and the team can click it to see the content. AI does not read deleted messages.' => '削除したメッセージはサーバーに保存されます。チャットには「このメッセージは削除されました」と表示され、チームはクリックして内容を確認できます。AIは削除されたメッセージを読みません。',
  'Message not found.' => 'メッセージが見つかりません。',
  'This message was already deleted.' => 'このメッセージはすでに削除されています。',
  'Only the sender or an administrator can delete this message for everyone.' => 'このメッセージを全員から削除できるのは送信者または管理者のみです。',
  'This message can\'t be deleted for everyone on this channel. You can hide it in the panel instead.' => 'このチャネルではこのメッセージを全員から削除できません。代わりにパネルで非表示にできます。',
  'The time limit for deleting for everyone has passed. You can hide it in the panel instead.' => '「全員から削除」の期限を過ぎました。代わりにパネルで非表示にできます。',
  'WhatsApp did not delete the message.' => 'WhatsAppでメッセージを削除できませんでした。',
  'Delete for everyone time limit (hours)' => '「全員から削除」の期限（時間）',
  'WhatsApp lets you delete a sent message for everyone only for about 2 days and 12 hours (60 hours). After this limit, or for received messages, the message is only hidden in the panel: it stays on the contact\'s phone. 0 turns off delete for everyone. Deleted messages are never removed from the server; the team can still open them.' => 'WhatsAppで送信済みメッセージを全員から削除できるのは約2日と12時間（60時間）までです。期限後や受信メッセージは、パネルでのみ非表示になり、相手の端末に残ります。0にすると「全員から削除」をオフにします。削除したメッセージはサーバーから消えず、チームは引き続き開けます。',
  'Last update request %1$s. While the panel is open it checks for new messages every %2$d s (3 s while a reply is streaming, up to 15 s when nothing changes) and once a minute in a background tab.' => '最終更新リクエスト %1$s。パネルが開いている間、%2$d 秒ごとに新しいメッセージを確認します（返信のストリーム中は 3 秒、変化がなければ最大 15 秒）。バックグラウンドのタブでは 1 分に 1 回です。',
  'The open tab checks for new messages at this interval (10 recommended), every 3 s while a reply is streaming, and up to 15 s when nothing changes. A background tab checks once a minute. Errors back off up to 60 s.' => '開いているタブはこの間隔（推奨 10）で新しいメッセージを確認します。返信のストリーム中は 3 秒ごと、変化がなければ最大 15 秒です。バックグラウンドのタブは 1 分に 1 回確認します。エラー時は間隔が最大 60 秒まで広がります。',
  'Flux Donate is not active.' => 'Flux Donate が有効ではありません。',
  'Donor\'s earlier referral' => '寄付者の以前の紹介者',
  'Referral' => '紹介者',
  'Order' => '注文',
  'Confirmation code' => '確認コード',
  'Recorded from' => '登録元',
  'Entered by' => '登録者',
  'Items' => '明細',
  'On behalf of: {n}' => '名義: {n}',
  'Receipts' => '振込明細',
  'Revoked' => '取り消し済み',
  '{n} paid gifts · {m}' => '支払い済み {n} 件 · {m}',
  'No contact details.' => '連絡先情報がありません。',
  'No referral.' => '紹介者なし。',
  'Has the payment reached the account? When you confirm, the certificate is made and sent to the donor.' => '入金は口座に届きましたか？確認すると証明書が作成され、寄付者に送られます。',

  'Change history' => '変更履歴',
  'Assistant memory' => 'アシスタントの記憶',
  'Note updated' => 'メモを更新しました',
  'Show less' => '表示を減らす',
  'Show all ({n})' => 'すべて表示 ({n})',
  'Filled from donation and certificate records (one-off update)' => '寄付・証明書の記録から入力 (1回限りの更新)',
  'Name given by the sending record' => '送信元の記録にある名前',
  'Filled from donation and certificate records' => '寄付・証明書の記録から入力',
  'The contact said their name in the chat' => '連絡先がチャットで名前を伝えました',
  'The contact corrected their name in the chat' => '連絡先がチャットで名前を訂正しました',
  'The contact gave their full name in the chat' => '連絡先がチャットでフルネームを伝えました',
  'The assistant updated the reminder: %1$s (%2$s)' => 'アシスタントがリマインダーを更新しました: %1$s (%2$s)',
  'The assistant marked the chat as completed (the person said goodbye). It continues normally if they write again.' => 'アシスタントがチャットを完了としてマークしました(相手が別れの挨拶をしました)。再度メッセージが届けば通常どおり続きます。',
  'Let the assistant react to messages with an emoji (👍 for "okay", 🤲 for thanks and prayers); once goodbyes are said it reacts instead of writing another farewell' => 'アシスタントがメッセージに絵文字でリアクションできるようにする(「了解」には👍、感謝や祈りには🤲)。別れの挨拶の後は、新たな挨拶を書かずにリアクションします',
  'same person and donation, not a copy' => '同じ人物・同じ寄付で、コピーではありません',
  'Closing, reactions and reminders' => '終了、リアクション、リマインダー',
  'Chat already marked completed (goodbyes said)' => 'チャットは既に完了としてマーク済み(別れの挨拶済み)',
  'Site search returns a sample event with a location' => 'サイト検索が場所付きのサンプルイベントを返す',
  'Chat marked completed' => 'チャットが完了としてマークされた',
  'Emoji reaction left' => '絵文字リアクションを付けた',
  'No text reply to the last message' => '最後のメッセージにテキスト返信なし',
  'Reminder is one-time' => 'リマインダーは1回限り',
  'Exactly one reminder' => 'リマインダーはちょうど1件',
  '(no text, reacted to the message: {e})' => '(テキストなし、メッセージへのリアクション: {e})',
  '(no text: the chat is completed, stayed silent)' => '(テキストなし: チャットは完了済みのため返信なし)',
  '(reacted to the message: {e})' => '(メッセージへのリアクション: {e})',
  'Reminder request: set at once' => 'リマインダーの依頼: すぐに設定',
  'Event location and time' => 'イベントの場所と時間',
  'Continuation: own receipt sent again, asks if it arrived' => '続き: 自分の領収書を再送し、届いたか尋ねる',
  'Thanks after help: one short farewell' => '対応後のお礼: 短い別れの挨拶を1回',
  'Goodbye loop: no repeated farewells' => '別れの挨拶のループ: 挨拶を繰り返さない',
  'New topic after goodbye gets a normal reply' => '別れの挨拶後の新しい話題には通常どおり返信',
  'Question after goodbye is answered' => '別れの挨拶後の質問に回答する',
  'Short "okay" after goodbye: reaction only' => '別れの挨拶後の短い「了解」: リアクションのみ',
  'Continuation: prayer gets a prayer reaction' => '続き: 祈りの言葉に祈りのリアクション',
  'Continuation: "you will remind me" sets the reminder at once' => '続き: 「リマインドしてくださいね」ですぐにリマインダーを設定',
  'Changes the day afterwards: same reminder updated' => '後から日付を変更: 同じリマインダーを更新',
  'Monthly reminder turned into one-time' => '毎月のリマインダーを1回限りに変更',
  'Has an active one-time reminder (just set)' => '有効な1回限りのリマインダーあり（設定直後）',
  'Reminder stopped' => 'リマインダー停止',
  'No 🙏 in reactions or replies' => 'リアクションと返信に🙏なし',
  'Continuation: "Kapat istemiyorum" stops the reminder at once' => '続き：「Kapat istemiyorum」でリマインダーをすぐ停止',
  'Continuation: "vazgeçtim" stops the reminder' => '続き：「vazgeçtim」でリマインダーを停止',
  'Continuation: complaint after a misread closes at once' => '続き：誤解の後の苦情ですぐ停止',
  'Goodbye reaction is 👍 or 🤲, never 🙏' => '別れのリアクションは👍か🤲、🙏は使わない',
 ),
);
